          .order('created_at', { ascending: false })
          .limit(1)
          .maybeSingle();

        if (complaint) {
          setHasExistingComplaint(true);
          setCurrentComplaintId(complaint.id);

          // جلب الرسائل السابقة من جدول complaint_messages إذا وجد
