إليك التحديث النهائي لملف `RecoveryForm.tsx`. لقد قمت بمعالجة مشكلة "اختفاء الطلب" من خلال التأكد من أن بيانات البلاغ الأولية يتم حفظها دائماً كرسائل في قاعدة البيانات فور التقديم، ومن ثم استرجاعها وترتيبها زمنياً عند إعادة فتح التطبيق.

### أولاً: كود قاعدة البيانات (تأكد من تنفيذه)
هذا الكود يضمن وجود الجداول والسياسات اللازمة:

```sql
-- جدول الرسائل
CREATE TABLE IF NOT EXISTS complaint_messages (
  id BIGSERIAL PRIMARY KEY,
  complaint_id INTEGER REFERENCES complaints(id) ON DELETE CASCADE,
  user_id UUID REFERENCES auth.users(id),
  text TEXT,
  image_url TEXT,
  sender TEXT CHECK (sender IN ('user', 'support')),
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- سياسات الأمان
ALTER TABLE complaint_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "view_own_messages" ON complaint_messages FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "insert_own_messages" ON complaint_messages FOR INSERT WITH CHECK (auth.uid() = user_id);

-- مخزن صور الدردشة
INSERT INTO storage.buckets (id, name, public) VALUES ('chat_images', 'chat_images', true) ON CONFLICT (id) DO NOTHING;
CREATE POLICY "upload_chat_img" ON storage.objects FOR INSERT WITH CHECK (bucket_id = 'chat_images');
CREATE POLICY "view_chat_img" ON storage.objects FOR SELECT USING (bucket_id = 'chat_images');
```

