        complaint_id: selectedId,
        user_id: user?.id,
        text: text,
        sender: 'support'
      }]);

      if (sendError) throw sendError;
      // لا نحتاج لتحديث الحالة يدوياً لأن الاشتراك (Subscription) سيتولى ذلك
