             <p>💰 المبلغ المتعثر: <span className="text-red-600 font-bold">{comp?.amount} USDT</span></p>
          </div>

          {messages.map((m) => (
            <div key={m.id} className={`max-w-[85%] ${m.sender === 'support' ? 'self-end' : 'self-start'}`}>
               <div className={`rounded-2xl overflow-hidden shadow-sm ${m.sender === 'support' ? 'bg-[#9B4A4E] text-white rounded-tr-none' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'}`}>
                 {m.image_url && <img src={m.image_url} className="w-full max-h-60 object-cover cursor-zoom-in" onClick={() => window.open(m.image_url, '_blank')} />}
                 {m.text && <div className="p-3 text-[11px] text-right whitespace-pre-wrap font-medium">{m.text}</div>}
                 <div className={`px-3 pb-1 flex items-center gap-1 text-[8px] ${m.sender === 'support' ? 'justify-start opacity-60' : 'justify-end opacity-40'}`}>
                   <span>{new Date(m.created_at).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
                   {m.sender === 'support' && <CheckCheck size={10} />}
                 </div>
               </div>
            </div>
          ))}
          <div ref={chatEndRef} />
        </div>

        <div className="p-4 border-t flex items-center gap-2 bg-white pb-10">
          <input 
            type="text" 
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
            placeholder="رد على العميل الآن..."
            className="flex-1 bg-gray-50 rounded-full px-5 py-3 text-xs text-right border border-gray-100 outline-none focus:border-[#9B4A4E] focus:ring-1 focus:ring-[#9B4A4E]/10"
            dir="rtl"
          />
          <button onClick={handleSendMessage} className="bg-[#9B4A4E] text-white p-3 rounded-full shadow-lg active:scale-90 transition-transform">
            <Send size={20} className="rotate-180" />
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4 py-2 animate-in fade-in duration-500">
      <div className="bg-white rounded-[32px] p-6 shadow-sm border border-gray-100 mb-6">
         <div className="flex items-center justify-between mb-6">
