            <div className="space-y-1">
              <p className="text-gray-500 text-xs font-black">لا توجد سجلات حالياً</p>
              <p className="text-gray-400 text-[10px]">بانتظار وصول شكاوي جديدة من العملاء...</p>
            </div>
          </div>
        ) : (
          filteredComplaints.map(c => {
            const timeDiff = new Date().getTime() - new Date(c.last_activity).getTime();
            const isJustActive = timeDiff < 60000; // نشط في آخر دقيقة

            return (
              <button 
