import React, { useState, useEffect, useRef, useMemo } from 'react';
import { supabase } from '../lib/supabase.ts';
import { MessageSquare, User, Clock, ChevronLeft, Send, Image as ImageIcon, CheckCheck, Loader2, Search, AlertCircle, RefreshCcw, ExternalLink, Paperclip, Pin, Sparkles, WifiOff } from 'lucide-react';

interface Complaint {
  id: string;
  created_at: string;
  amount: number;
  mission_id: string;
  platform_link: string;
  user_id: string;
  last_activity: string; 
  profiles?: {
    full_name: string;
    customer_code: string;
  };
}

const AdminDashboard: React.FC = () => {
  const [complaints, setComplaints] = useState<Complaint[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  // دالة جلب البيانات مع فصل الطلبات لضمان عدم حدوث خطأ "Failed to fetch" بسبب الربط (Joins)
  const fetchComplaints = async () => {
    setLoading(true);
    setError(null);
    try {
      // 1. جلب الشكاوى أولاً بشكل مستقل
      const { data: rawComps, error: rawError } = await supabase
        .from('complaints')
        .select('*')
        .order('created_at', { ascending: false });

      if (rawError) throw rawError;

      if (!rawComps || rawComps.length === 0) {
        setComplaints([]);
        setLoading(false);
        return;
      }

      // 2. جلب البروفايلات المرتبطة يدوياً لتجنب مشاكل علاقات قاعدة البيانات
      const userIds = [...new Set(rawComps.map(c => c.user_id))];
      const { data: profiles, error: profileError } = await supabase
        .from('profiles')
        .select('id, full_name, customer_code')
        .in('id', userIds);

      // 3. جلب أحدث تاريخ لكل محادثة من جدول الرسائل
      const { data: lastMsgs, error: msgError } = await supabase
        .from('complaint_messages')
        .select('complaint_id, created_at')
        .order('created_at', { ascending: false });

      // 4. دمج البيانات وتحديد وقت آخر نشاط (Last Activity)
      const processed = rawComps.map(c => {
        const latestMsg = lastMsgs?.find(m => m.complaint_id === c.id);
        return {
          ...c,
          profiles: profiles?.find(p => p.id === c.user_id),
          last_activity: latestMsg ? latestMsg.created_at : c.created_at
        } as Complaint;
      });

      setComplaints(processed);
    } catch (err: any) {
      console.error("Supabase Fetch Error:", err);
      setError("حدث خطأ في الاتصال بالسيرفر. يرجى التأكد من استقرار الإنترنت وتنشيط الصفحة.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchComplaints();

    // نظام التحديث الفوري والترتيب التلقائي (Real-time Ranking)
    const channel = supabase.channel('admin_live_sync')
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaint_messages' 
      }, (payload) => {
        const newMsg = payload.new;

        // إعادة ترتيب القائمة فوراً: الدردشة التي استقبلت رسالة تصعد للمقدمة
        setComplaints(prev => {
          const index = prev.findIndex(c => c.id === newMsg.complaint_id);
          if (index === -1) return prev;

          const updated = [...prev];
          const item = { ...updated[index], last_activity: newMsg.created_at };
          updated.splice(index, 1);
          updated.unshift(item); // دفع للأعلى فوراً
          return updated;
        });

        // إذا كان المسؤول يفتح هذه الدردشة حالياً، يتم إضافة الرسالة للواجهة
        if (selectedId === newMsg.complaint_id) {
          setMessages(prev => {
            if (prev.find(m => m.id === newMsg.id)) return prev;
            return [...prev, newMsg];
          });
        }
      })
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaints' 
      }, () => {
        // تحديث السجل عند وصول شكوى جديدة من عميل جديد
        fetchComplaints();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [selectedId]);

  // جلب الرسائل عند اختيار دردشة محددة
  useEffect(() => {
    if (!selectedId) return;
    const loadMessages = async () => {
      const { data } = await supabase
        .from('complaint_messages')
        .select('*')
        .eq('complaint_id', selectedId)
        .order('created_at', { ascending: true });
      if (data) setMessages(data);
    };
    loadMessages();
  }, [selectedId]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !selectedId) return;
    const text = inputValue;
    setInputValue('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      const { error: sendError } = await supabase.from('complaint_messages').insert([{
        complaint_id: selectedId,
        user_id: user?.id,
        text: text,
        sender: 'support'
      }]);
      if (sendError) throw sendError;
    } catch (err: any) {
      setError("فشل إرسال الرد، يرجى المحاولة مرة أخرى.");
      setInputValue(text);
    }
  };

  // تصفية السجل مع الحفاظ على الترتيب حسب آخر نشاط
  const filteredComplaints = useMemo(() => {
    return complaints
      .filter(c => 
        searchQuery === '' ||
        c.profiles?.full_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.mission_id?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.amount.toString().includes(searchQuery)
      )
      .sort((a, b) => new Date(b.last_activity).getTime() - new Date(a.last_activity).getTime());
  }, [complaints, searchQuery]);

  if (loading && complaints.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center p-24 gap-4">
        <Loader2 className="animate-spin text-[#9B4A4E]" size={40} />
        <p className="text-gray-400 text-[10px] font-black tracking-widest">جاري مزامنة السجلات المباشرة...</p>
      </div>
    );
  }

  // واجهة الدردشة المفتوحة
  if (selectedId) {
    const comp = complaints.find(c => c.id === selectedId);
    return (
      <div className="fixed inset-0 z-[110] bg-[#F8FAFC] flex flex-col max-w-[430px] mx-auto animate-in slide-in-from-left duration-300">
        {/* الهيدر العلوي */}
        <div className="bg-[#9B4A4E] text-white px-4 pt-12 pb-4 flex items-center gap-3 shadow-xl z-30">
          <button onClick={() => setSelectedId(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <ChevronLeft size={24} />
          </button>
          <div className="flex-1 text-right">
            <h2 className="text-sm font-bold truncate">{comp?.profiles?.full_name || 'عميل'}</h2>
            <p className="text-[9px] opacity-70">كود العميل: {comp?.profiles?.customer_code || '---'}</p>
          </div>
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center border border-white/10 shadow-inner">
             <User size={20} />
          </div>
        </div>

        {/* منطقة الرسائل مع كارت البيانات الثابت */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 pb-32">
          {/* كارت البيانات الأصلي - لا يختفي أبداً عند الرد */}
          <div className="bg-white p-4 rounded-3xl border border-[#9B4A4E]/20 shadow-md text-right sticky top-0 z-20">
             <div className="flex items-center gap-2 mb-3 text-[#9B4A4E] font-bold text-[10px] border-b border-gray-50 pb-2">
                <Pin size={14} className="rotate-45" /> بيانات المهمة والمتنازع عليها
             </div>
             <div className="grid grid-cols-2 gap-3 mb-3">
               <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100/50">
                 <p className="text-gray-400 text-[8px] mb-1 font-bold">المبلغ</p>
                 <p className="text-red-600 font-black text-xs">{comp?.amount} USDT</p>
               </div>
               <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100/50">
                 <p className="text-gray-400 text-[8px] mb-1 font-bold">رقم المهمة</p>
                 <p className="text-gray-800 font-bold text-xs">#{comp?.mission_id}</p>
               </div>
             </div>
             <div className="bg-blue-50/50 p-2.5 rounded-xl border border-blue-100/30">
                <p className="text-[9px] text-blue-600 truncate underline">{comp?.platform_link}</p>
             </div>
          </div>

          {/* عرض المحادثة */}
          {messages.map((m) => (
            <div key={m.id} className={`max-w-[85%] flex flex-col ${m.sender === 'support' ? 'self-end' : 'self-start'}`}>
               <div className={`rounded-2xl overflow-hidden shadow-sm ${m.sender === 'support' ? 'bg-[#9B4A4E] text-white rounded-tr-none' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'}`}>
                 {m.image_url && (
                   <div className="relative group">
                     <img 
                       src={m.image_url} 
                       className="w-full max-h-96 object-contain bg-black/5 cursor-pointer hover:brightness-95 transition-all" 
                       onClick={() => window.open(m.image_url, '_blank')} 
                     />
                     <div className="absolute top-2 left-2 bg-black/40 p-2 rounded-full backdrop-blur-md opacity-0 group-hover:opacity-100 transition-opacity">
                        <ExternalLink size={14} className="text-white" />
                     </div>
                   </div>
                 )}
                 {m.text && <div className="p-3 text-[11px] text-right whitespace-pre-wrap leading-relaxed font-medium">{m.text}</div>}
                 <div className={`px-3 pb-1.5 flex items-center gap-1 text-[8px] ${m.sender === 'support' ? 'justify-start opacity-60' : 'justify-end opacity-40'}`}>
                   <span>{new Date(m.created_at).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
                   {m.sender === 'support' && <CheckCheck size={10} />}
                 </div>
               </div>
            </div>
          ))}
          <div ref={chatEndRef} />
        </div>

        {/* حقل الإدخال */}
        <div className="p-4 border-t flex items-center gap-2 bg-white pb-10 shadow-[0_-10px_25px_rgba(0,0,0,0.05)] z-30">
          <input 
            type="text" 
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
            placeholder="اكتب رد المسؤول..."
            className="flex-1 bg-gray-50 rounded-full px-5 py-4 text-xs text-right border border-gray-100 outline-none focus:border-[#9B4A4E] focus:bg-white transition-all shadow-inner"
            dir="rtl"
