  // تحديث المرجع عند تغيير المعرف المختار لضمان وصول القيمة الصحيحة لردود الفعل (Callbacks)
  useEffect(() => {
    selectedIdRef.current = selectedId;
  }, [selectedId]);

  const fetchComplaints = async () => {
    setLoading(true);
    setError(null);
    try {
      const { data: rawComps, error: rawError } = await supabase
        .from('complaints')
        .select('*')
        .order('created_at', { ascending: false });

      if (rawError) throw rawError;

      if (!rawComps || rawComps.length === 0) {
        setComplaints([]);
        setLoading(false);
        return;
      }

      const userIds = [...new Set(rawComps.map(c => c.user_id))];
      const { data: profiles } = await supabase
        .from('profiles')
        .select('id, full_name, customer_code')
        .in('id', userIds);

      const { data: lastMsgs } = await supabase
        .from('complaint_messages')
        .select('complaint_id, created_at')
        .order('created_at', { ascending: false });

      const processed = rawComps.map(c => {
        const latestMsg = lastMsgs?.find(m => m.complaint_id === c.id);
        return {
          ...c,
          profiles: profiles?.find(p => p.id === c.user_id),
          last_activity: latestMsg ? latestMsg.created_at : c.created_at
        } as Complaint;
      });

      setComplaints(processed);
    } catch (err: any) {
      console.error("Fetch Error:", err);
      setError("خطأ في الاتصال بالسيرفر. يرجى التنشيط.");
    } finally {
      setLoading(false);
    }
  };

  // إعداد الاشتراك الفوري (Real-time)
  useEffect(() => {
    fetchComplaints();

    // قناة الاستماع الموحدة للرسائل الجديدة والشكاوى الجديدة
    const channel = supabase.channel('admin_global_realtime')
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaint_messages' 
      }, (payload) => {
        const newMsg = payload.new;

        // 1. تحديث ترتيب القائمة فوراً (نقل الدردشة للأعلى)
        setComplaints(prev => {
          const index = prev.findIndex(c => c.id === newMsg.complaint_id);
          if (index === -1) return prev; // إذا لم تكن في القائمة بعد (نحتاج لعمل fetch للجديد)

          const updated = [...prev];
          const item = { ...updated[index], last_activity: newMsg.created_at };
          updated.splice(index, 1);
          updated.unshift(item); 
          return updated;
        });

        // 2. تحديث نافذة الدردشة المفتوحة حالياً (مثل واتساب)
        if (selectedIdRef.current === newMsg.complaint_id) {
          setMessages(prev => {
            if (prev.find(m => m.id === newMsg.id)) return prev;
            return [...prev, newMsg];
          });
        }
      })
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaints' 
      }, () => {
        fetchComplaints(); // جلب الشكاوى الجديدة فوراً
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  // جلب الرسائل عند فتح محادثة
  useEffect(() => {
    if (!selectedId) {
      setMessages([]);
      return;
    }
    const loadMessages = async () => {
      const { data } = await supabase
        .from('complaint_messages')
        .select('*')
        .eq('complaint_id', selectedId)
        .order('created_at', { ascending: true });
      if (data) setMessages(data);
    };
    loadMessages();
  }, [selectedId]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !selectedId) return;
    const text = inputValue;
    setInputValue('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      await supabase.from('complaint_messages').insert([{
        complaint_id: selectedId,
        user_id: user?.id,
        text: text,
        sender: 'support'
      }]);
      // لا نحتاج لتحديث الـ state يدوياً هنا لأن الـ Real-time سيقوم بذلك فوراً
    } catch (err: any) {
      console.error("Send Error:", err);
      setInputValue(text);
    }
  };

  const filteredComplaints = useMemo(() => {
    return complaints
      .filter(c => 
        searchQuery === '' ||
        c.profiles?.full_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.mission_id?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.amount.toString().includes(searchQuery)
      )
      .sort((a, b) => new Date(b.last_activity).getTime() - new Date(a.last_activity).getTime());
  }, [complaints, searchQuery]);

  if (loading && complaints.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center p-24 gap-4">
        <Loader2 className="animate-spin text-[#9B4A4E]" size={40} />
        <p className="text-gray-400 text-[10px] font-black tracking-widest">جاري المزامنة المباشرة...</p>
      </div>
    );
  }

  if (selectedId) {
    const comp = complaints.find(c => c.id === selectedId);
    return (
      <div className="fixed inset-0 z-[110] bg-[#F8FAFC] flex flex-col max-w-[430px] mx-auto animate-in slide-in-from-left duration-300">
        {/* هيدر الدردشة */}
        <div className="bg-[#9B4A4E] text-white px-4 pt-12 pb-4 flex items-center gap-3 shadow-xl z-30">
          <button onClick={() => setSelectedId(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <ChevronLeft size={24} />
          </button>
          <div className="flex-1 text-right">
            <h2 className="text-sm font-bold truncate">{comp?.profiles?.full_name || 'عميل'}</h2>
            <p className="text-[9px] opacity-70">كود: {comp?.profiles?.customer_code || '---'}</p>
          </div>
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center border border-white/10 shadow-inner">
             <User size={20} />
          </div>
        </div>

        {/* المحتوى مع كارت البيانات الثابت */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 pb-32">
          {/* كارت البيانات الأصلي - ثابت ولا يختفي أبداً */}
          <div className="bg-white p-4 rounded-3xl border border-[#9B4A4E]/20 shadow-md text-right sticky top-0 z-20">
             <div className="flex items-center gap-2 mb-3 text-[#9B4A4E] font-bold text-[10px] border-b border-gray-50 pb-2">
                <Pin size={14} className="rotate-45" /> البيانات الأصلية للطلب
             </div>
             <div className="grid grid-cols-2 gap-3 mb-3">
               <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100/50">
                 <p className="text-gray-400 text-[8px] mb-1 font-bold">المبلغ المطلوب</p>
                 <p className="text-red-600 font-black text-xs">{comp?.amount} USDT</p>
               </div>
               <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100/50">
                 <p className="text-gray-400 text-[8px] mb-1 font-bold">رقم المهمة</p>
                 <p className="text-gray-800 font-bold text-xs">#{comp?.mission_id}</p>
               </div>
             </div>
             {comp?.screenshot_url && (
               <div className="mb-3 rounded-xl overflow-hidden border border-gray-100">
                  <p className="text-[8px] text-gray-400 mb-1 font-bold">لقطة الشاشة الأصلية:</p>
                  <img src={comp.screenshot_url} className="w-full h-24 object-cover cursor-pointer hover:scale-105 transition-transform" onClick={() => window.open(comp.screenshot_url, '_blank')} />
               </div>
             )}
             <div className="bg-blue-50/50 p-2.5 rounded-xl border border-blue-100/30 flex items-center justify-between">
                <p className="text-[9px] text-blue-600 truncate underline flex-1 ml-2">{comp?.platform_link}</p>
                <ExternalLink size={12} className="text-blue-400" />
             </div>
          </div>

          {/* الرسائل المباشرة */}
          {messages.map((m) => (
            <div key={m.id} className={`max-w-[85%] flex flex-col ${m.sender === 'support' ? 'self-end' : 'self-start'}`}>
               <div className={`rounded-2xl overflow-hidden shadow-sm ${m.sender === 'support' ? 'bg-[#9B4A4E] text-white rounded-tr-none' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'}`}>
                 {m.image_url && (
                   <div className="relative group">
                     <img 
                       src={m.image_url} 
                       className="w-full max-h-96 object-contain bg-black/5 cursor-pointer" 
                       onClick={() => window.open(m.image_url, '_blank')} 
                     />
                   </div>
                 )}
                 {m.text && <div className="p-3 text-[11px] text-right whitespace-pre-wrap leading-relaxed font-medium">{m.text}</div>}
                 <div className={`px-3 pb-1.5 flex items-center gap-1 text-[8px] ${m.sender === 'support' ? 'justify-start opacity-60' : 'justify-end opacity-40'}`}>
                   <span>{new Date(m.created_at).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
                   {m.sender === 'support' && <CheckCheck size={10} />}
                 </div>
               </div>
            </div>
          ))}
          <div ref={chatEndRef} />
        </div>

        {/* حقل الرد الفوري */}
        <div className="p-4 border-t flex items-center gap-2 bg-white pb-10 shadow-[0_-10px_25px_rgba(0,0,0,0.05)] z-30">
          <input 
            type="text" 
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
            placeholder="اكتب رد المسؤول..."
            className="flex-1 bg-gray-50 rounded-full px-5 py-4 text-xs text-right border border-gray-100 outline-none focus:border-[#9B4A4E] transition-all shadow-inner"
            dir="rtl"
          />
          <button onClick={handleSendMessage} className="bg-[#9B4A4E] text-white p-4 rounded-full shadow-lg active:scale-90 transition-transform">
            <Send size={20} className="rotate-180" />
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4 py-2 animate-in fade-in duration-500">
      {/* البحث والوضع المباشر */}
      <div className="bg-white rounded-[32px] p-6 shadow-sm border border-gray-100 mb-6 mx-1">
         <div className="flex items-center justify-between mb-6">
            <button onClick={fetchComplaints} className="p-2 text-gray-300 hover:text-[#9B4A4E] transition-all active:rotate-180">
              <RefreshCcw size={18} className={loading ? 'animate-spin text-[#9B4A4E]' : ''} />
            </button>
            <div className="text-right">
              <h2 className="font-black text-gray-800 text-lg">لوحة الرصد الفوري</h2>
              <div className="flex items-center gap-1 justify-end mt-1">
                 <span className="text-[10px] text-green-500 font-black">وضع واتساب نَشط</span>
                 <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_5px_green]"></div>
              </div>
            </div>
         </div>
         <div className="relative">
            <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
            <input 
              type="text" 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="ابحث بالاسم أو المهمة..." 
              className="w-full bg-gray-50 rounded-2xl py-4 px-12 text-xs text-right border-none shadow-inner outline-none focus:ring-1 focus:ring-[#9B4A4E]/20" 
              dir="rtl" 
            />
         </div>
      </div>

      {/* قائمة الدردشات مرتبة تلقائياً */}
      <div className="space-y-3 px-1 pb-32">
        {filteredComplaints.length === 0 && !loading ? (
          <div className="text-center py-24 flex flex-col items-center gap-4">
            <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center text-gray-200">
              <MessageSquare size={40} />
            </div>
            <p className="text-gray-500 text-xs font-black">لا توجد سجلات حالياً</p>
          </div>
        ) : (
          filteredComplaints.map(c => {
            const isJustActive = (new Date().getTime() - new Date(c.last_activity).getTime()) < 60000;
            return (
              <button 
                key={c.id} 
                onClick={() => setSelectedId(c.id)}
                className={`w-full bg-white p-5 rounded-[28px] flex items-center gap-4 border shadow-sm active:scale-[0.98] transition-all text-right hover:border-[#9B4A4E]/30 group relative overflow-hidden ${isJustActive ? 'border-[#9B4A4E]/30 ring-1 ring-[#9B4A4E]/5 shadow-md' : 'border-gray-50'}`}
              >
                {isJustActive && (
                  <div className="absolute top-0 right-0 p-1.5 bg-[#9B4A4E] text-white rounded-bl-xl shadow-md flex items-center gap-1">
                     <Sparkles size={10} />
                     <span className="text-[7px] font-black">نشط الآن</span>
                  </div>
                )}
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-inner transition-all ${isJustActive ? 'bg-[#9B4A4E]/10 text-[#9B4A4E]' : 'bg-gray-50 text-gray-400 group-hover:bg-[#9B4A4E]/5'}`}>
                  <User size={28} strokeWidth={1.5} />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex justify-between items-start mb-1">
                    <span className="text-[8px] font-bold text-gray-400">
                      {new Date(c.last_activity).toLocaleTimeString('ar-EG', {hour:'2-digit', minute:'2-digit'})}
                    </span>
                    <h4 className="font-bold text-gray-800 text-sm truncate ml-2">
                      {c.profiles?.full_name || 'عميل'}
                    </h4>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-[11px] font-black text-[#9B4A4E]">{c.amount} USDT</span>
                    <p className="text-[9px] text-gray-400 font-bold bg-gray-50 px-2 py-0.5 rounded-md">
                      #{c.mission_id}
                    </p>
                  </div>
                </div>
                <ChevronLeft size={16} className="text-gray-200 group-hover:text-[#9B4A4E]" />
              </button>
            );
          })
        )}
      </div>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useRef, useEffect } from 'react';
import { Gavel, Send, ChevronRight, MoreVertical, CheckCheck, Loader2, MessageSquareText, Camera, Image as ImageIcon, Paperclip } from 'lucide-react';
import { supabase } from '../lib/supabase.ts';

interface Message {
  id: number;
  text?: string;
  imageUrl?: string;
  sender: 'user' | 'support';
  time: string;
}

const RecoveryForm: React.FC = () => {
  const [isChatActive, setIsChatActive] = useState(false);
  const [hasExistingComplaint, setHasExistingComplaint] = useState(false);
  const [currentComplaintId, setCurrentComplaintId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isChatUploading, setIsChatUploading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [formData, setFormData] = useState({ link: '', missionId: '', amount: '', reason: 'تجميد الرصيد' });
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatImageRef = useRef<HTMLInputElement>(null);

  const formatTime = (date: string | Date) => new Date(date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  // جلب البيانات الأولية والاشتراك في التحديثات الفورية
  useEffect(() => {
    let channel: any;

    async function checkStatus() {
      try {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return;

        const { data: complaint } = await supabase
          .from('complaints')
          .select('*')
          .eq('user_id', user.id)
          .order('created_at', { ascending: false })
          .limit(1)
          .maybeSingle();

        if (complaint) {
          setHasExistingComplaint(true);
          setCurrentComplaintId(complaint.id);

          const { data: dbMsgs } = await supabase
            .from('complaint_messages')
            .select('*')
            .eq('complaint_id', complaint.id)
            .order('created_at', { ascending: true });

          if (dbMsgs) {
            setMessages(dbMsgs.map(m => ({ 
              id: m.id, 
              text: m.text, 
              imageUrl: m.image_url, 
              sender: m.sender, 
              time: formatTime(m.created_at) 
            })));
          }

          // الاشتراك في الرسائل الجديدة لهذا العميل فوراً
          channel = supabase.channel(`chat_user_${complaint.id}`)
            .on('postgres_changes', { 
              event: 'INSERT', 
              schema: 'public', 
              table: 'complaint_messages', 
              filter: `complaint_id=eq.${complaint.id}` 
            }, (payload) => {
              const newMsg = payload.new;
              setMessages(prev => {
                if (prev.find(m => m.id === newMsg.id)) return prev;
                return [...prev, {
                  id: newMsg.id,
                  text: newMsg.text,
                  imageUrl: newMsg.image_url,
                  sender: newMsg.sender,
                  time: formatTime(newMsg.created_at)
                }];
              });
            })
            .subscribe();
        }
      } finally { setLoading(false); }
    }
    checkStatus();

    return () => {
      if (channel) supabase.removeChannel(channel);
    };
  }, []);

  useEffect(() => {
    if (isChatActive) chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, isChatActive]);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !currentComplaintId) return;
    const text = inputValue;
    setInputValue('');
    const { data: { user } } = await supabase.auth.getUser();
    await supabase.from('complaint_messages').insert([{ 
      complaint_id: currentComplaintId, 
      user_id: user?.id, 
      text: text, 
      sender: 'user' 
    }]);
    // التحديث سيتم تلقائياً عبر Real-time channel
  };

  const handleChatImage = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !currentComplaintId) return;
    setIsChatUploading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      const fileName = `${user?.id}/${Date.now()}.jpg`;
      await supabase.storage.from('chat_images').upload(fileName, file);
      const { data: { publicUrl } } = supabase.storage.from('chat_images').getPublicUrl(fileName);
      await supabase.from('complaint_messages').insert([{ 
        complaint_id: currentComplaintId, 
        user_id: user?.id, 
        image_url: publicUrl, 
        sender: 'user' 
      }]);
    } finally { setIsChatUploading(false); }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedImage) return;
    setIsSubmitting(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      const fileName = `initial/${user?.id}-${Date.now()}.jpg`;
      await supabase.storage.from('complaints').upload(fileName, selectedImage);
      const { data: { publicUrl } } = supabase.storage.from('complaints').getPublicUrl(fileName);

      const { data: comp } = await supabase.from('complaints').insert([{ 
        user_id: user?.id, 
        platform_link: formData.link, 
        mission_id: formData.missionId, 
        amount: parseFloat(formData.amount), 
        reason: formData.reason, 
        screenshot_url: publicUrl 
      }]).select().single();

      if (comp) {
        const reportText = `📋 *تفاصيل الطلب:*\nالرابط: ${formData.link}\nالمهمة: #${formData.missionId}\nالمبلغ: ${formData.amount} USDT`;
        await supabase.from('complaint_messages').insert([
          { complaint_id: comp.id, user_id: user?.id, image_url: publicUrl, sender: 'user' },
          { complaint_id: comp.id, user_id: user?.id, text: reportText, sender: 'user' }
        ]);

        // إعادة تحميل الصفحة لتنشيط قناة الـ Real-time للشكوى الجديدة
        window.location.reload();
      }
    } finally { setIsSubmitting(false); }
  };

  if (loading) return <div className="p-10 flex justify-center"><Loader2 className="animate-spin text-[#9B4A4E]" /></div>;

  if (isChatActive) {
    return (
      <div className="fixed inset-0 z-[100] bg-[#F4F7F9] flex flex-col max-w-[430px] mx-auto">
        <div className="bg-[#9B4A4E] text-white px-4 pt-12 pb-4 flex items-center gap-3 shadow-lg">
          <button onClick={() => setIsChatActive(false)}><ChevronRight size={28} /></button>
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center overflow-hidden border border-white/10 shadow-inner">
             <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Naser" className="w-full h-full" />
          </div>
          <div className="flex-1 text-right">
            <h2 className="text-sm font-bold">ناصر - مراجعة المرفقات</h2>
            <p className="text-[9px] opacity-70">متصل الآن لمراجعة طلبك</p>
          </div>
          <MoreVertical size={20} className="opacity-40" />
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 flex flex-col">
          {messages.map((msg) => (
            <div key={msg.id} className={`max-w-[85%] ${msg.sender === 'user' ? 'self-end' : 'self-start'}`}>
              <div className={`rounded-2xl overflow-hidden shadow-sm ${msg.sender === 'user' ? 'bg-[#9B4A4E] text-white rounded-tr-none' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'}`}>
                {msg.imageUrl && <img src={msg.imageUrl} className="w-full max-h-64 object-cover" />}
                {msg.text && <div className="p-3 text-[11px] text-right whitespace-pre-wrap leading-relaxed font-medium">{msg.text}</div>}
                <div className={`px-3 pb-1.5 flex items-center gap-1 text-[8px] opacity-60 ${msg.sender === 'user' ? 'justify-start' : 'justify-end'}`}>
                  <span>{msg.time}</span>
                  {msg.sender === 'user' && <CheckCheck size={10} />}
                </div>
              </div>
            </div>
          ))}
          {isChatUploading && <div className="self-end text-[9px] text-[#9B4A4E] animate-pulse">جاري إرسال الصورة...</div>}
          <div ref={chatEndRef} />
        </div>

        <div className="bg-white p-4 pb-8 border-t flex items-center gap-3 shadow-inner">
          <button onClick={() => chatImageRef.current?.click()} className="p-2 text-gray-400 hover:text-[#9B4A4E]"><ImageIcon size={22} /></button>
          <input type="file" ref={chatImageRef} className="hidden" accept="image/*" onChange={handleChatImage} />
          <input type="text" value={inputValue} onChange={(e) => setInputValue(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()} placeholder="اكتب رسالتك..." className="flex-1 bg-gray-50 rounded-full px-4 py-3 text-xs text-right border-none outline-none focus:ring-1 focus:ring-[#9B4A4E]/20 transition-all" dir="rtl" />
          <button onClick={handleSendMessage} className="bg-[#9B4A4E] text-white p-3 rounded-full shadow-lg active:scale-90 transition-all"><Send size={18} className="rotate-180" /></button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-3xl p-6 shadow-xl border border-gray-100">
      {hasExistingComplaint ? (
        <div className="flex flex-col items-center text-center py-4">
          <div className="w-20 h-20 bg-green-50 rounded-full flex items-center justify-center mb-4"><MessageSquareText size={36} className="text-green-600" /></div>
          <h3 className="font-bold text-gray-800">طلبك قيد المراجعة الفورية</h3>
          <p className="text-[11px] text-gray-500 mt-2 mb-6 px-4">تم تسجيل بياناتك بنجاح. تواصل مع الوكيل ناصر لمتابعة استرداد أموالك.</p>
          <button onClick={() => setIsChatActive(true)} className="w-full bg-[#9B4A4E] text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 shadow-lg active:scale-95 transition-transform">
            <Paperclip size={20} /> عرض المرفقات والدردشة المباشرة
          </button>
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-4">
          <input type="text" required placeholder="رابط المنصة" value={formData.link} onChange={e => setFormData({...formData, link: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border-none shadow-inner" />
          <div className="grid grid-cols-2 gap-3">
            <input type="text" required placeholder="رقم المهمة" value={formData.missionId} onChange={e => setFormData({...formData, missionId: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border-none shadow-inner" />
            <input type="number" required placeholder="المبلغ USDT" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border-none shadow-inner" />
          </div>
          <div onClick={() => fileInputRef.current?.click()} className="w-full aspect-video rounded-2xl border-2 border-dashed border-gray-200 flex flex-col items-center justify-center bg-gray-50 cursor-pointer overflow-hidden relative group">
            {imagePreview ? <img src={imagePreview} className="w-full h-full object-cover" /> : <div className="text-center transition-transform group-hover:scale-110"><Camera className="mx-auto text-gray-300 mb-2" size={32} /><p className="text-[9px] text-gray-400 font-bold">أرفق لقطة شاشة للمهمة</p></div>}
          </div>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) { setSelectedImage(f); const r = new FileReader(); r.onloadend = () => setImagePreview(r.result as string); r.readAsDataURL(f); } }} />
          <button type="submit" disabled={isSubmitting || !selectedImage} className="w-full bg-[#9B4A4E] text-white font-bold py-4 rounded-2xl disabled:opacity-50 flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-all">
            {isSubmitting ? <Loader2 className="animate-spin" /> : 'تقديم الشكوى الآن'}
          </button>
        </form>
      )}
    </div>
  );
};

export default RecoveryForm;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { supabase } from '../lib/supabase.ts';
import { MessageSquare, User, Clock, ChevronLeft, Send, Image as ImageIcon, CheckCheck, Loader2, Search, AlertCircle, RefreshCcw, ExternalLink, Paperclip, Pin, Sparkles, WifiOff } from 'lucide-react';

interface Complaint {
  id: string;
  created_at: string;
  amount: number;
  mission_id: string;
  platform_link: string;
  user_id: string;
  last_activity: string; 
  screenshot_url?: string;
  profiles?: {
    full_name: string;
    customer_code: string;
  };
}

const AdminDashboard: React.FC = () => {
  const [complaints, setComplaints] = useState<Complaint[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const selectedIdRef = useRef<string | null>(null);

  // تحديث مرجع المعرف المختار لتجنب Stale Closures في الـ Callbacks
  useEffect(() => {
    selectedIdRef.current = selectedId;
    if (selectedId) {
      loadMessages(selectedId);
    }
  }, [selectedId]);

  const loadMessages = async (id: string) => {
    const { data } = await supabase
      .from('complaint_messages')
      .select('*')
      .eq('complaint_id', id)
      .order('created_at', { ascending: true });
    if (data) setMessages(data);
  };

  const fetchComplaints = async () => {
    try {
      const { data: rawComps, error: rawError } = await supabase
        .from('complaints')
        .select('*')
        .order('created_at', { ascending: false });

      if (rawError) throw rawError;
      if (!rawComps) return;

      const userIds = [...new Set(rawComps.map(c => c.user_id))];
      const { data: profiles } = await supabase
        .from('profiles')
        .select('id, full_name, customer_code')
        .in('id', userIds);

      const { data: lastMsgs } = await supabase
        .from('complaint_messages')
        .select('complaint_id, created_at')
        .order('created_at', { ascending: false });

      const processed = rawComps.map(c => {
        const latestMsg = lastMsgs?.find(m => m.complaint_id === c.id);
        return {
          ...c,
          profiles: profiles?.find(p => p.id === c.user_id),
          last_activity: latestMsg ? latestMsg.created_at : c.created_at
        } as Complaint;
      });

      setComplaints(processed);
    } catch (err: any) {
      console.error("Fetch Error:", err);
      setError("خطأ في الاتصال. يرجى التنشيط.");
    } finally {
      setLoading(false);
    }
  };

  // الاشتراك الفوري العالمي (Real-time)
  useEffect(() => {
    fetchComplaints();

    const channel = supabase.channel('whatsapp_admin_sync')
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaint_messages' 
      }, (payload) => {
        const newMsg = payload.new;

        // 1. تحديث قائمة الدردشات فوراً (نقل للأعلى)
        setComplaints(prev => {
          const index = prev.findIndex(c => c.id === newMsg.complaint_id);
          if (index === -1) return prev;

          const updated = [...prev];
          const item = { ...updated[index], last_activity: newMsg.created_at };
          updated.splice(index, 1);
          updated.unshift(item);
          return updated;
        });

        // 2. تحديث نافذة الدردشة المفتوحة فوراً
        if (selectedIdRef.current === newMsg.complaint_id) {
          setMessages(prev => {
            if (prev.find(m => m.id === newMsg.id)) return prev;
            return [...prev, newMsg];
          });
          // تمرير لأسفل تلقائي
          setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
        }
      })
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaints' 
      }, () => {
        fetchComplaints();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'auto' });
  }, [messages]);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !selectedId) return;
    const text = inputValue;
    setInputValue('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { error: sendError } = await supabase.from('complaint_messages').insert([{
        complaint_id: selectedId,
        user_id: user.id,
        text: text,
        sender: 'support'
      }]);

      if (sendError) throw sendError;
    } catch (err: any) {
      console.error("Send Error:", err);
      setInputValue(text);
    }
  };

  const filteredComplaints = useMemo(() => {
    return complaints
      .filter(c => 
        searchQuery === '' ||
        c.profiles?.full_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.mission_id?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.amount.toString().includes(searchQuery)
      )
      .sort((a, b) => new Date(b.last_activity).getTime() - new Date(a.last_activity).getTime());
  }, [complaints, searchQuery]);

  if (loading && complaints.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center p-24 gap-4">
        <Loader2 className="animate-spin text-[#9B4A4E]" size={40} />
        <p className="text-gray-400 text-[10px] font-black tracking-widest">مزامنة فورية للمحادثات...</p>
      </div>
    );
  }

  if (selectedId) {
    const comp = complaints.find(c => c.id === selectedId);
    return (
      <div className="fixed inset-0 z-[110] bg-[#F8FAFC] flex flex-col max-w-[430px] mx-auto animate-in slide-in-from-left duration-300">
        <div className="bg-[#9B4A4E] text-white px-4 pt-12 pb-4 flex items-center gap-3 shadow-xl z-30">
          <button onClick={() => setSelectedId(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <ChevronLeft size={24} />
          </button>
          <div className="flex-1 text-right">
            <h2 className="text-sm font-bold truncate">{comp?.profiles?.full_name || 'عميل'}</h2>
            <p className="text-[9px] opacity-70">كود: {comp?.profiles?.customer_code || '---'}</p>
          </div>
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center border border-white/10 shadow-inner">
             <User size={20} />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 pb-32">
          <div className="bg-white p-4 rounded-3xl border border-[#9B4A4E]/20 shadow-md text-right sticky top-0 z-20">
             <div className="flex items-center gap-2 mb-3 text-[#9B4A4E] font-bold text-[10px] border-b border-gray-50 pb-2">
                <Pin size={14} className="rotate-45" /> البيانات الأصلية للطلب
             </div>
             <div className="grid grid-cols-2 gap-3 mb-3">
               <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100/50">
                 <p className="text-gray-400 text-[8px] mb-1 font-bold">المبلغ المطلوب</p>
                 <p className="text-red-600 font-black text-xs">{comp?.amount} USDT</p>
               </div>
               <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100/50">
                 <p className="text-gray-400 text-[8px] mb-1 font-bold">رقم المهمة</p>
                 <p className="text-gray-800 font-bold text-xs">#{comp?.mission_id}</p>
               </div>
             </div>
             <div className="bg-blue-50/50 p-2.5 rounded-xl border border-blue-100/30 flex items-center justify-between">
                <p className="text-[9px] text-blue-600 truncate underline flex-1 ml-2">{comp?.platform_link}</p>
                <ExternalLink size={12} className="text-blue-400" />
             </div>
          </div>

          {messages.map((m) => (
            <div key={m.id} className={`max-w-[85%] flex flex-col ${m.sender === 'support' ? 'self-end' : 'self-start'}`}>
               <div className={`rounded-2xl overflow-hidden shadow-sm ${m.sender === 'support' ? 'bg-[#9B4A4E] text-white rounded-tr-none' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'}`}>
                 {m.image_url && (
                   <div className="relative group">
                     <img 
                       src={m.image_url} 
                       className="w-full max-h-96 object-contain bg-black/5 cursor-pointer" 
                       onClick={() => window.open(m.image_url, '_blank')} 
                     />
                   </div>
                 )}
                 {m.text && <div className="p-3 text-[11px] text-right whitespace-pre-wrap leading-relaxed font-medium">{m.text}</div>}
                 <div className={`px-3 pb-1.5 flex items-center gap-1 text-[8px] ${m.sender === 'support' ? 'justify-start opacity-60' : 'justify-end opacity-40'}`}>
                   <span>{new Date(m.created_at).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
                   {m.sender === 'support' && <CheckCheck size={10} />}
                 </div>
               </div>
            </div>
          ))}
          <div ref={chatEndRef} />
        </div>

        <div className="p-4 border-t flex items-center gap-2 bg-white pb-10 shadow-[0_-10px_25px_rgba(0,0,0,0.05)] z-30">
          <input 
            type="text" 
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
            placeholder="اكتب رد المسؤول..."
            className="flex-1 bg-gray-50 rounded-full px-5 py-4 text-xs text-right border border-gray-100 outline-none focus:border-[#9B4A4E] transition-all shadow-inner"
            dir="rtl"
          />
          <button onClick={handleSendMessage} className="bg-[#9B4A4E] text-white p-4 rounded-full shadow-lg active:scale-90 transition-transform">
            <Send size={20} className="rotate-180" />
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4 py-2 animate-in fade-in duration-500">
      <div className="bg-white rounded-[32px] p-6 shadow-sm border border-gray-100 mb-6 mx-1">
         <div className="flex items-center justify-between mb-6">
            <button onClick={fetchComplaints} className="p-2 text-gray-300 hover:text-[#9B4A4E] transition-all active:rotate-180">
              <RefreshCcw size={18} className={loading ? 'animate-spin text-[#9B4A4E]' : ''} />
            </button>
            <div className="text-right">
              <h2 className="font-black text-gray-800 text-lg">لوحة الرصد الفوري</h2>
              <div className="flex items-center gap-1 justify-end mt-1">
                 <span className="text-[10px] text-green-500 font-black">وضع المزامنة نَشط</span>
                 <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_5px_green]"></div>
              </div>
            </div>
         </div>
         <div className="relative">
            <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
            <input 
              type="text" 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="ابحث بالاسم أو المهمة..." 
              className="w-full bg-gray-50 rounded-2xl py-4 px-12 text-xs text-right border-none shadow-inner outline-none focus:ring-1 focus:ring-[#9B4A4E]/20" 
              dir="rtl" 
            />
         </div>
      </div>

      <div className="space-y-3 px-1 pb-32">
        {filteredComplaints.length === 0 && !loading ? (
          <div className="text-center py-24 flex flex-col items-center gap-4">
            <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center text-gray-200">
              <MessageSquare size={40} />
            </div>
            <p className="text-gray-500 text-xs font-black">لا توجد سجلات حالياً</p>
          </div>
        ) : (
          filteredComplaints.map(c => {
            const isJustActive = (new Date().getTime() - new Date(c.last_activity).getTime()) < 30000;
            return (
              <button 
                key={c.id} 
                onClick={() => setSelectedId(c.id)}
                className={`w-full bg-white p-5 rounded-[28px] flex items-center gap-4 border shadow-sm active:scale-[0.98] transition-all text-right hover:border-[#9B4A4E]/30 group relative overflow-hidden ${isJustActive ? 'border-[#9B4A4E]/30 ring-1 ring-[#9B4A4E]/5 shadow-md' : 'border-gray-50'}`}
              >
                {isJustActive && (
                  <div className="absolute top-0 right-0 p-1.5 bg-[#9B4A4E] text-white rounded-bl-xl shadow-md flex items-center gap-1">
                     <Sparkles size={10} />
                     <span className="text-[7px] font-black">نشط الآن</span>
                  </div>
                )}
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-inner transition-all ${isJustActive ? 'bg-[#9B4A4E]/10 text-[#9B4A4E]' : 'bg-gray-50 text-gray-400 group-hover:bg-[#9B4A4E]/5'}`}>
                  <User size={28} strokeWidth={1.5} />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex justify-between items-start mb-1">
                    <span className="text-[8px] font-bold text-gray-400">
                      {new Date(c.last_activity).toLocaleTimeString('ar-EG', {hour:'2-digit', minute:'2-digit'})}
                    </span>
                    <h4 className="font-bold text-gray-800 text-sm truncate ml-2">
                      {c.profiles?.full_name || 'عميل'}
                    </h4>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-[11px] font-black text-[#9B4A4E]">{c.amount} USDT</span>
                    <p className="text-[9px] text-gray-400 font-bold bg-gray-50 px-2 py-0.5 rounded-md">
                      #{c.mission_id}
                    </p>
                  </div>
                </div>
                <ChevronLeft size={16} className="text-gray-200 group-hover:text-[#9B4A4E]" />
              </button>
            );
          })
        )}
      </div>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useRef, useEffect } from 'react';
import { Gavel, Send, ChevronRight, MoreVertical, CheckCheck, Loader2, MessageSquareText, Camera, Image as ImageIcon, Paperclip } from 'lucide-react';
import { supabase } from '../lib/supabase.ts';

interface Message {
  id: any;
  text?: string;
  imageUrl?: string;
  sender: 'user' | 'support';
  time: string;
}

const RecoveryForm: React.FC = () => {
  const [isChatActive, setIsChatActive] = useState(false);
  const [hasExistingComplaint, setHasExistingComplaint] = useState(false);
  const [currentComplaintId, setCurrentComplaintId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isChatUploading, setIsChatUploading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [formData, setFormData] = useState({ link: '', missionId: '', amount: '', reason: 'تجميد الرصيد' });
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatImageRef = useRef<HTMLInputElement>(null);

  const formatTime = (date: string | Date) => new Date(date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  // التحقق من وجود شكوى سابقة وجلب الرسائل
  useEffect(() => {
    async function checkStatus() {
      try {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return;

        const { data: complaint } = await supabase
          .from('complaints')
          .select('*')
          .eq('user_id', user.id)
          .order('created_at', { ascending: false })
          .limit(1)
          .maybeSingle();

        if (complaint) {
          setHasExistingComplaint(true);
          setCurrentComplaintId(complaint.id);

          const { data: dbMsgs } = await supabase
            .from('complaint_messages')
            .select('*')
            .eq('complaint_id', complaint.id)
            .order('created_at', { ascending: true });

          if (dbMsgs) {
            setMessages(dbMsgs.map(m => ({ 
              id: m.id, 
              text: m.text, 
              imageUrl: m.image_url, 
              sender: m.sender, 
              time: formatTime(m.created_at) 
            })));
          }
        }
      } catch (e) {
        console.error(e);
      } finally { 
        setLoading(false); 
      }
    }
    checkStatus();
  }, []);

  // المزامنة الفورية للعميل (Real-time)
  useEffect(() => {
    if (!currentComplaintId) return;

    const channel = supabase.channel(`whatsapp_user_${currentComplaintId}`)
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaint_messages', 
        filter: `complaint_id=eq.${currentComplaintId}` 
      }, (payload) => {
        const newMsg = payload.new;
        setMessages(prev => {
          if (prev.find(m => m.id === newMsg.id)) return prev;
          return [...prev, {
            id: newMsg.id,
            text: newMsg.text,
            imageUrl: newMsg.image_url,
            sender: newMsg.sender,
            time: formatTime(newMsg.created_at)
          }];
        });
        // تمرير لأسفل عند وصول رسالة جديدة
        setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [currentComplaintId]);

  // التمرير التلقائي عند فتح الدردشة أو تغير الرسائل
  useEffect(() => {
    if (isChatActive) {
      chatEndRef.current?.scrollIntoView({ behavior: 'auto' });
    }
  }, [messages, isChatActive]);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !currentComplaintId) return;
    const text = inputValue;
    setInputValue('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { error } = await supabase.from('complaint_messages').insert([{ 
        complaint_id: currentComplaintId, 
        user_id: user.id, 
        text: text, 
        sender: 'user' 
      }]);

      if (error) throw error;
    } catch (e) {
      console.error(e);
      setInputValue(text);
    }
  };

  const handleChatImage = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !currentComplaintId) return;
    setIsChatUploading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const fileName = `${user.id}/${Date.now()}.jpg`;
      await supabase.storage.from('chat_images').upload(fileName, file);
      const { data: { publicUrl } } = supabase.storage.from('chat_images').getPublicUrl(fileName);

      await supabase.from('complaint_messages').insert([{ 
        complaint_id: currentComplaintId, 
        user_id: user.id, 
        image_url: publicUrl, 
        sender: 'user' 
      }]);
    } catch (e) {
      console.error(e);
    } finally { 
      setIsChatUploading(false); 
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedImage) return;
    setIsSubmitting(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const fileName = `initial/${user.id}-${Date.now()}.jpg`;
      await supabase.storage.from('complaints').upload(fileName, selectedImage);
      const { data: { publicUrl } } = supabase.storage.from('complaints').getPublicUrl(fileName);

      const { data: comp, error: compErr } = await supabase.from('complaints').insert([{ 
        user_id: user.id, 
        platform_link: formData.link, 
        mission_id: formData.missionId, 
        amount: parseFloat(formData.amount), 
        reason: formData.reason, 
        screenshot_url: publicUrl 
      }]).select().single();

      if (compErr) throw compErr;

      if (comp) {
        const reportText = `📋 *تفاصيل الطلب:*\nالرابط: ${formData.link}\nالمهمة: #${formData.missionId}\nالمبلغ: ${formData.amount} USDT`;
        await supabase.from('complaint_messages').insert([
          { complaint_id: comp.id, user_id: user.id, image_url: publicUrl, sender: 'user' },
          { complaint_id: comp.id, user_id: user.id, text: reportText, sender: 'user' }
        ]);

        setCurrentComplaintId(comp.id);
        setHasExistingComplaint(true);
      }
    } catch (e) {
      console.error(e);
      alert("حدث خطأ في تقديم الشكوى.");
    } finally { 
      setIsSubmitting(false); 
    }
  };

  if (loading) return <div className="p-10 flex justify-center"><Loader2 className="animate-spin text-[#9B4A4E]" /></div>;

  if (isChatActive) {
    return (
      <div className="fixed inset-0 z-[100] bg-[#F4F7F9] flex flex-col max-w-[430px] mx-auto">
        <div className="bg-[#9B4A4E] text-white px-4 pt-12 pb-4 flex items-center gap-3 shadow-lg">
          <button onClick={() => setIsChatActive(false)}><ChevronRight size={28} /></button>
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center overflow-hidden border border-white/10 shadow-inner">
             <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Naser" className="w-full h-full" />
          </div>
          <div className="flex-1 text-right">
            <h2 className="text-sm font-bold">ناصر - مراجعة المرفقات</h2>
            <p className="text-[9px] opacity-70">متصل الآن لمراجعة طلبك</p>
          </div>
          <MoreVertical size={20} className="opacity-40" />
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 flex flex-col">
          {messages.map((msg) => (
            <div key={msg.id} className={`max-w-[85%] ${msg.sender === 'user' ? 'self-end' : 'self-start'}`}>
              <div className={`rounded-2xl overflow-hidden shadow-sm ${msg.sender === 'user' ? 'bg-[#9B4A4E] text-white rounded-tr-none' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'}`}>
                {msg.imageUrl && <img src={msg.imageUrl} className="w-full max-h-64 object-cover" />}
                {msg.text && <div className="p-3 text-[11px] text-right whitespace-pre-wrap leading-relaxed font-medium">{msg.text}</div>}
                <div className={`px-3 pb-1.5 flex items-center gap-1 text-[8px] opacity-60 ${msg.sender === 'user' ? 'justify-start' : 'justify-end'}`}>
                  <span>{msg.time}</span>
                  {msg.sender === 'user' && <CheckCheck size={10} />}
                </div>
              </div>
            </div>
          ))}
          {isChatUploading && <div className="self-end text-[9px] text-[#9B4A4E] animate-pulse">جاري إرسال الصورة...</div>}
          <div ref={chatEndRef} />
        </div>

        <div className="bg-white p-4 pb-8 border-t flex items-center gap-3 shadow-inner">
          <button onClick={() => chatImageRef.current?.click()} className="p-2 text-gray-400 hover:text-[#9B4A4E]"><ImageIcon size={22} /></button>
          <input type="file" ref={chatImageRef} className="hidden" accept="image/*" onChange={handleChatImage} />
          <input type="text" value={inputValue} onChange={(e) => setInputValue(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()} placeholder="اكتب رسالتك..." className="flex-1 bg-gray-50 rounded-full px-4 py-3 text-xs text-right border-none outline-none focus:ring-1 focus:ring-[#9B4A4E]/20 transition-all" dir="rtl" />
          <button onClick={handleSendMessage} className="bg-[#9B4A4E] text-white p-3 rounded-full shadow-lg active:scale-90 transition-all"><Send size={18} className="rotate-180" /></button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-3xl p-6 shadow-xl border border-gray-100">
      {hasExistingComplaint ? (
        <div className="flex flex-col items-center text-center py-4">
          <div className="w-20 h-20 bg-green-50 rounded-full flex items-center justify-center mb-4"><MessageSquareText size={36} className="text-green-600" /></div>
          <h3 className="font-bold text-gray-800">طلبك قيد المراجعة الفورية</h3>
          <p className="text-[11px] text-gray-500 mt-2 mb-6 px-4">تم تسجيل بياناتك بنجاح. تواصل مع الوكيل ناصر لمتابعة استرداد أموالك.</p>
          <button onClick={() => setIsChatActive(true)} className="w-full bg-[#9B4A4E] text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 shadow-lg active:scale-95 transition-transform">
            <Paperclip size={20} /> عرض المرفقات والدردشة المباشرة
          </button>
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-4">
          <input type="text" required placeholder="رابط المنصة" value={formData.link} onChange={e => setFormData({...formData, link: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border-none shadow-inner" />
          <div className="grid grid-cols-2 gap-3">
            <input type="text" required placeholder="رقم المهمة" value={formData.missionId} onChange={e => setFormData({...formData, missionId: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border-none shadow-inner" />
            <input type="number" required placeholder="المبلغ USDT" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border-none shadow-inner" />
          </div>
          <div onClick={() => fileInputRef.current?.click()} className="w-full aspect-video rounded-2xl border-2 border-dashed border-gray-200 flex flex-col items-center justify-center bg-gray-50 cursor-pointer overflow-hidden relative group">
            {imagePreview ? <img src={imagePreview} className="w-full h-full object-cover" /> : <div className="text-center transition-transform group-hover:scale-110"><Camera className="mx-auto text-gray-300 mb-2" size={32} /><p className="text-[9px] text-gray-400 font-bold">أرفق لقطة شاشة للمهمة</p></div>}
          </div>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) { setSelectedImage(f); const r = new FileReader(); r.onloadend = () => setImagePreview(r.result as string); r.readAsDataURL(f); } }} />
          <button type="submit" disabled={isSubmitting || !selectedImage} className="w-full bg-[#9B4A4E] text-white font-bold py-4 rounded-2xl disabled:opacity-50 flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-all">
            {isSubmitting ? <Loader2 className="animate-spin" /> : 'تقديم الشكوى الآن'}
          </button>
        </form>
      )}
    </div>
  );
};

export default RecoveryForm;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { supabase } from '../lib/supabase.ts';
import { MessageSquare, User, Clock, ChevronLeft, Send, Image as ImageIcon, CheckCheck, Loader2, Search, AlertCircle, RefreshCcw, ExternalLink, Paperclip, Pin, Sparkles, WifiOff } from 'lucide-react';

interface Complaint {
  id: string;
  created_at: string;
  amount: number;
  mission_id: string;
  platform_link: string;
  user_id: string;
  last_activity: string; 
  screenshot_url?: string;
  profiles?: {
    full_name: string;
    customer_code: string;
  };
}

const AdminDashboard: React.FC = () => {
  const [complaints, setComplaints] = useState<Complaint[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const selectedIdRef = useRef<string | null>(null);

  // تحديث مرجع المعرف المختار لحظياً
  useEffect(() => {
    selectedIdRef.current = selectedId;
    if (selectedId) {
      loadMessages(selectedId);
    }
  }, [selectedId]);

  const loadMessages = async (id: string) => {
    const { data } = await supabase
      .from('complaint_messages')
      .select('*')
      .eq('complaint_id', id)
      .order('created_at', { ascending: true });
    if (data) setMessages(data);
  };

  const fetchComplaints = async () => {
    try {
      const { data: rawComps, error: rawError } = await supabase
        .from('complaints')
        .select('*')
        .order('created_at', { ascending: false });

      if (rawError) throw rawError;
      if (!rawComps) return;

      const userIds = [...new Set(rawComps.map(c => c.user_id))];
      const { data: profiles } = await supabase
        .from('profiles')
        .select('id, full_name, customer_code')
        .in('id', userIds);

      const { data: lastMsgs } = await supabase
        .from('complaint_messages')
        .select('complaint_id, created_at')
        .order('created_at', { ascending: false });

      const processed = rawComps.map(c => {
        const latestMsg = lastMsgs?.find(m => m.complaint_id === c.id);
        return {
          ...c,
          profiles: profiles?.find(p => p.id === c.user_id),
          last_activity: latestMsg ? latestMsg.created_at : c.created_at
        } as Complaint;
      });

      setComplaints(processed);
    } catch (err: any) {
      console.error("Fetch Error:", err);
      setError("خطأ في الاتصال بالسيرفر.");
    } finally {
      setLoading(false);
    }
  };

  // المزامنة الفورية (Real-time) - واتساب ستايل
  useEffect(() => {
    fetchComplaints();

    const channel = supabase.channel('whatsapp_admin_v2')
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaint_messages' 
      }, (payload) => {
        const newMsg = payload.new;

        // 1. تحديث ترتيب القائمة (صعود الدردشة النشطة للأعلى)
        setComplaints(prev => {
          const index = prev.findIndex(c => c.id === newMsg.complaint_id);
          if (index === -1) return prev;

          const updated = [...prev];
          const item = { ...updated[index], last_activity: newMsg.created_at };
          updated.splice(index, 1);
          updated.unshift(item);
          return updated;
        });

        // 2. تحديث المحادثة المفتوحة حالياً (لحظياً)
        if (selectedIdRef.current === newMsg.complaint_id) {
          setMessages(prev => {
            // منع التكرار (في حال كان تم إضافته يدوياً عند الإرسال)
            if (prev.find(m => m.id === newMsg.id)) return prev;
            return [...prev, newMsg];
          });
        }
      })
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaints' 
      }, () => {
        fetchComplaints();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  // التمرير التلقائي للأسفل
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !selectedId) return;
    const text = inputValue;
    setInputValue('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      // إضافة الرسالة للواجهة "تفاؤلياً" لضمان السرعة (Optimistic Update)
      const tempId = Date.now();
      const optimisticMsg = {
        id: tempId,
        complaint_id: selectedId,
        user_id: user.id,
        text: text,
        sender: 'support',
        created_at: new Date().toISOString()
      };
      setMessages(prev => [...prev, optimisticMsg]);

      const { data: sentMsg, error: sendError } = await supabase.from('complaint_messages').insert([{
        complaint_id: selectedId,
        user_id: user.id,
        text: text,
        sender: 'support'
      }]).select().single();

      if (sendError) throw sendError;

      // تحديث المعرف المؤقت بالمعرف الحقيقي من قاعدة البيانات
      setMessages(prev => prev.map(m => m.id === tempId ? sentMsg : m));

    } catch (err: any) {
      console.error("Send Error:", err);
      // في حال الفشل، نقوم بإزالة الرسالة المتفائلة وإرجاع النص للحقل
      setInputValue(text);
      setMessages(prev => prev.filter(m => typeof m.id !== 'number')); // إزالة المؤقت
      alert("فشل إرسال الرسالة، يرجى المحاولة لاحقاً.");
    }
  };

  const filteredComplaints = useMemo(() => {
    return complaints
      .filter(c => 
        searchQuery === '' ||
        c.profiles?.full_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.mission_id?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.amount.toString().includes(searchQuery)
      )
      .sort((a, b) => new Date(b.last_activity).getTime() - new Date(a.last_activity).getTime());
  }, [complaints, searchQuery]);

  if (loading && complaints.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center p-24 gap-4">
        <Loader2 className="animate-spin text-[#9B4A4E]" size={40} />
        <p className="text-gray-400 text-[10px] font-black tracking-widest">تنشيط المزامنة المباشرة...</p>
      </div>
    );
  }

  if (selectedId) {
    const comp = complaints.find(c => c.id === selectedId);
    return (
      <div className="fixed inset-0 z-[110] bg-[#F8FAFC] flex flex-col max-w-[430px] mx-auto">
        {/* هيدر الدردشة */}
        <div className="bg-[#9B4A4E] text-white px-4 pt-12 pb-4 flex items-center gap-3 shadow-xl z-30">
          <button onClick={() => setSelectedId(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <ChevronLeft size={24} />
          </button>
          <div className="flex-1 text-right">
            <h2 className="text-sm font-bold truncate">{comp?.profiles?.full_name || 'عميل'}</h2>
            <p className="text-[9px] opacity-70">كود: {comp?.profiles?.customer_code || '---'}</p>
          </div>
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center border border-white/10 shadow-inner">
             <User size={20} />
          </div>
        </div>

        {/* الرسائل */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 pb-32 bg-[#f0f2f5]">
          <div className="bg-white p-4 rounded-3xl border border-[#9B4A4E]/20 shadow-md text-right sticky top-0 z-20">
             <div className="flex items-center gap-2 mb-3 text-[#9B4A4E] font-bold text-[10px] border-b border-gray-50 pb-2">
                <Pin size={14} className="rotate-45" /> البيانات الأصلية للطلب
             </div>
             <div className="grid grid-cols-2 gap-3 mb-3">
               <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100/50">
                 <p className="text-gray-400 text-[8px] mb-1 font-bold">المبلغ</p>
                 <p className="text-red-600 font-black text-xs">{comp?.amount} USDT</p>
               </div>
               <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100/50">
                 <p className="text-gray-400 text-[8px] mb-1 font-bold">المهمة</p>
                 <p className="text-gray-800 font-bold text-xs">#{comp?.mission_id}</p>
               </div>
             </div>
             <div className="bg-blue-50/50 p-2.5 rounded-xl border border-blue-100/30">
                <p className="text-[9px] text-blue-600 truncate underline">{comp?.platform_link}</p>
             </div>
          </div>

          {messages.map((m) => (
            <div key={m.id} className={`max-w-[85%] flex flex-col ${m.sender === 'support' ? 'self-end' : 'self-start'}`}>
               <div className={`rounded-2xl overflow-hidden shadow-sm ${m.sender === 'support' ? 'bg-[#9B4A4E] text-white rounded-tr-none' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'}`}>
                 {m.image_url && (
                   <img src={m.image_url} className="w-full max-h-96 object-contain bg-black/5" />
                 )}
                 {m.text && <div className="p-3 text-[11px] text-right whitespace-pre-wrap leading-relaxed font-medium">{m.text}</div>}
                 <div className={`px-3 pb-1.5 flex items-center gap-1 text-[8px] ${m.sender === 'support' ? 'justify-start opacity-60' : 'justify-end opacity-40'}`}>
                   <span>{new Date(m.created_at).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
                   {m.sender === 'support' && <CheckCheck size={10} />}
                 </div>
               </div>
            </div>
          ))}
          <div ref={chatEndRef} />
        </div>

        {/* حقل الإرسال */}
        <div className="p-4 border-t flex items-center gap-2 bg-white pb-10 shadow-[0_-10px_25px_rgba(0,0,0,0.05)] z-30">
          <input 
            type="text" 
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
            placeholder="اكتب رد المسؤول..."
            className="flex-1 bg-gray-50 rounded-full px-5 py-4 text-xs text-right border border-gray-100 outline-none focus:border-[#9B4A4E] transition-all"
            dir="rtl"
          />
          <button onClick={handleSendMessage} className="bg-[#9B4A4E] text-white p-4 rounded-full shadow-lg active:scale-90 transition-transform">
            <Send size={20} className="rotate-180" />
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4 py-2 animate-in fade-in duration-500">
      <div className="bg-white rounded-[32px] p-6 shadow-sm border border-gray-100 mb-6 mx-1">
         <div className="flex items-center justify-between mb-6 text-right">
            <button onClick={fetchComplaints} className="p-2 text-gray-300 hover:text-[#9B4A4E]">
              <RefreshCcw size={18} className={loading ? 'animate-spin text-[#9B4A4E]' : ''} />
            </button>
            <div>
              <h2 className="font-black text-gray-800 text-lg">لوحة الرصد الفوري</h2>
              <div className="flex items-center gap-1 justify-end mt-1">
                 <span className="text-[10px] text-green-500 font-black">المزامنة نَشطة الآن</span>
                 <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_5px_green]"></div>
              </div>
            </div>
         </div>
         <div className="relative">
            <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
            <input 
              type="text" 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="ابحث بالاسم أو المهمة..." 
              className="w-full bg-gray-50 rounded-2xl py-4 px-12 text-xs text-right border-none shadow-inner outline-none focus:ring-1 focus:ring-[#9B4A4E]/20" 
              dir="rtl" 
            />
         </div>
      </div>

      <div className="space-y-3 px-1 pb-32">
        {filteredComplaints.length === 0 && !loading ? (
          <div className="text-center py-24 flex flex-col items-center gap-4 text-gray-400">
            <MessageSquare size={40} />
            <p className="text-xs font-black">لا توجد محادثات نشطة</p>
          </div>
        ) : (
          filteredComplaints.map(c => {
            const isJustActive = (new Date().getTime() - new Date(c.last_activity).getTime()) < 30000;
            return (
              <button 
                key={c.id} 
                onClick={() => setSelectedId(c.id)}
                className={`w-full bg-white p-5 rounded-[28px] flex items-center gap-4 border shadow-sm active:scale-[0.98] transition-all text-right hover:border-[#9B4A4E]/30 relative overflow-hidden ${isJustActive ? 'border-[#9B4A4E]/30 ring-1 ring-[#9B4A4E]/5 shadow-md' : 'border-gray-50'}`}
              >
                {isJustActive && (
                  <div className="absolute top-0 right-0 p-1.5 bg-[#9B4A4E] text-white rounded-bl-xl shadow-md flex items-center gap-1">
                     <Sparkles size={10} />
                     <span className="text-[7px] font-black">جديد</span>
                  </div>
                )}
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${isJustActive ? 'bg-[#9B4A4E]/10 text-[#9B4A4E]' : 'bg-gray-50 text-gray-400'}`}>
                  <User size={28} strokeWidth={1.5} />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex justify-between items-start mb-1">
                    <span className="text-[8px] font-bold text-gray-400">
                      {new Date(c.last_activity).toLocaleTimeString('ar-EG', {hour:'2-digit', minute:'2-digit'})}
                    </span>
                    <h4 className="font-bold text-gray-800 text-sm truncate ml-2">
                      {c.profiles?.full_name || 'عميل'}
                    </h4>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-[11px] font-black text-[#9B4A4E]">{c.amount} USDT</span>
                    <p className="text-[9px] text-gray-400 font-bold bg-gray-50 px-2 py-0.5 rounded-md">
                      #{c.mission_id}
                    </p>
                  </div>
                </div>
                <ChevronLeft size={16} className="text-gray-200" />
              </button>
            );
          })
        )}
      </div>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useRef, useEffect } from 'react';
import { Gavel, Send, ChevronRight, MoreVertical, CheckCheck, Loader2, MessageSquareText, Camera, Image as ImageIcon, Paperclip } from 'lucide-react';
import { supabase } from '../lib/supabase.ts';

interface Message {
  id: any;
  text?: string;
  imageUrl?: string;
  sender: 'user' | 'support';
  time: string;
}

const RecoveryForm: React.FC = () => {
  const [isChatActive, setIsChatActive] = useState(false);
  const [hasExistingComplaint, setHasExistingComplaint] = useState(false);
  const [currentComplaintId, setCurrentComplaintId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isChatUploading, setIsChatUploading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [formData, setFormData] = useState({ link: '', missionId: '', amount: '', reason: 'تجميد الرصيد' });
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatImageRef = useRef<HTMLInputElement>(null);

  const formatTime = (date: string | Date) => new Date(date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  // التحقق الأولي
  useEffect(() => {
    async function checkStatus() {
      try {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return;

        const { data: complaint } = await supabase
          .from('complaints')
          .select('*')
          .eq('user_id', user.id)
          .order('created_at', { ascending: false })
          .limit(1)
          .maybeSingle();

        if (complaint) {
          setHasExistingComplaint(true);
          setCurrentComplaintId(complaint.id);

          const { data: dbMsgs } = await supabase
            .from('complaint_messages')
            .select('*')
            .eq('complaint_id', complaint.id)
            .order('created_at', { ascending: true });

          if (dbMsgs) {
            setMessages(dbMsgs.map(m => ({ 
              id: m.id, 
              text: m.text, 
              imageUrl: m.image_url, 
              sender: m.sender, 
              time: formatTime(m.created_at) 
            })));
          }
        }
      } catch (e) {
        console.error(e);
      } finally { 
        setLoading(false); 
      }
    }
    checkStatus();
  }, []);

  // المزامنة الفورية (Real-time) للعميل
  useEffect(() => {
    if (!currentComplaintId) return;

    const channel = supabase.channel(`whatsapp_client_${currentComplaintId}`)
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaint_messages', 
        filter: `complaint_id=eq.${currentComplaintId}` 
      }, (payload) => {
        const newMsg = payload.new;
        setMessages(prev => {
          // منع التكرار (لأننا نضيف الرسالة يدوياً عند الإرسال)
          if (prev.find(m => m.id === newMsg.id)) return prev;
          return [...prev, {
            id: newMsg.id,
            text: newMsg.text,
            imageUrl: newMsg.image_url,
            sender: newMsg.sender,
            time: formatTime(newMsg.created_at)
          }];
        });
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [currentComplaintId]);

  // تمرير تلقائي للأسفل لحظي
  useEffect(() => {
    if (isChatActive) {
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isChatActive]);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !currentComplaintId) return;
    const text = inputValue;
    const now = new Date();
    setInputValue('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      // إضافة تفاؤلية (Optimistic Update) لضمان الاستجابة اللحظية
      const tempId = Date.now();
      const optimisticMsg: Message = {
        id: tempId,
        text: text,
        sender: 'user',
        time: formatTime(now)
      };
      setMessages(prev => [...prev, optimisticMsg]);

      const { data: sentMsg, error } = await supabase.from('complaint_messages').insert([{ 
        complaint_id: currentComplaintId, 
        user_id: user.id, 
        text: text, 
        sender: 'user' 
      }]).select().single();

      if (error) throw error;

      // تحديث المعرف المؤقت بالمعرف الحقيقي
      setMessages(prev => prev.map(m => m.id === tempId ? {
        id: sentMsg.id,
        text: sentMsg.text,
        imageUrl: sentMsg.image_url,
        sender: sentMsg.sender,
        time: formatTime(sentMsg.created_at)
      } : m));

    } catch (e) {
      console.error(e);
      setInputValue(text); // إعادة النص في حال الفشل
      setMessages(prev => prev.filter(m => typeof m.id !== 'number'));
    }
  };

  const handleChatImage = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !currentComplaintId) return;
    setIsChatUploading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const fileName = `${user.id}/${Date.now()}.jpg`;
      await supabase.storage.from('chat_images').upload(fileName, file);
      const { data: { publicUrl } } = supabase.storage.from('chat_images').getPublicUrl(fileName);

      await supabase.from('complaint_messages').insert([{ 
        complaint_id: currentComplaintId, 
        user_id: user.id, 
        image_url: publicUrl, 
        sender: 'user' 
      }]);
    } catch (e) {
      console.error(e);
    } finally { 
      setIsChatUploading(false); 
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedImage) return;
    setIsSubmitting(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const fileName = `initial/${user.id}-${Date.now()}.jpg`;
      await supabase.storage.from('complaints').upload(fileName, selectedImage);
      const { data: { publicUrl } } = supabase.storage.from('complaints').getPublicUrl(fileName);

      const { data: comp, error: compErr } = await supabase.from('complaints').insert([{ 
        user_id: user.id, 
        platform_link: formData.link, 
        mission_id: formData.missionId, 
        amount: parseFloat(formData.amount), 
        reason: formData.reason, 
        screenshot_url: publicUrl 
      }]).select().single();

      if (compErr) throw compErr;

      if (comp) {
        const reportText = `📋 *تفاصيل الطلب:*\nالرابط: ${formData.link}\nالمهمة: #${formData.missionId}\nالمبلغ: ${formData.amount} USDT`;
        await supabase.from('complaint_messages').insert([
          { complaint_id: comp.id, user_id: user.id, image_url: publicUrl, sender: 'user' },
          { complaint_id: comp.id, user_id: user.id, text: reportText, sender: 'user' }
        ]);

        setCurrentComplaintId(comp.id);
        setHasExistingComplaint(true);
      }
    } catch (e) {
      console.error(e);
      alert("حدث خطأ في تقديم الشكوى.");
    } finally { 
      setIsSubmitting(false); 
    }
  };

  if (loading) return <div className="p-10 flex justify-center"><Loader2 className="animate-spin text-[#9B4A4E]" /></div>;

  if (isChatActive) {
    return (
      <div className="fixed inset-0 z-[100] bg-[#F4F7F9] flex flex-col max-w-[430px] mx-auto">
        <div className="bg-[#9B4A4E] text-white px-4 pt-12 pb-4 flex items-center gap-3 shadow-lg">
          <button onClick={() => setIsChatActive(false)}><ChevronRight size={28} /></button>
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center overflow-hidden border border-white/10 shadow-inner">
             <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Naser" className="w-full h-full" />
          </div>
          <div className="flex-1 text-right">
            <h2 className="text-sm font-bold">ناصر - مراجعة المرفقات</h2>
            <p className="text-[9px] opacity-70">متصل الآن للمراجعة</p>
          </div>
          <MoreVertical size={20} className="opacity-40" />
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 flex flex-col bg-[#e5ddd5]">
          {messages.map((msg) => (
            <div key={msg.id} className={`max-w-[85%] ${msg.sender === 'user' ? 'self-end' : 'self-start'}`}>
              <div className={`rounded-2xl overflow-hidden shadow-sm ${msg.sender === 'user' ? 'bg-[#dcf8c6] text-gray-800 rounded-tr-none border border-black/5' : 'bg-white text-gray-800 rounded-tl-none border border-gray-200'}`}>
                {msg.imageUrl && <img src={msg.imageUrl} className="w-full max-h-64 object-cover" />}
                {msg.text && <div className="p-3 text-[11px] text-right whitespace-pre-wrap leading-relaxed font-medium">{msg.text}</div>}
                <div className={`px-3 pb-1.5 flex items-center gap-1 text-[8px] opacity-60 ${msg.sender === 'user' ? 'justify-start' : 'justify-end'}`}>
                  <span>{msg.time}</span>
                  {msg.sender === 'user' && <CheckCheck size={10} />}
                </div>
              </div>
            </div>
          ))}
          {isChatUploading && <div className="self-end text-[9px] text-[#9B4A4E] animate-pulse">جاري إرسال المرفق...</div>}
          <div ref={chatEndRef} />
        </div>

        <div className="bg-white p-4 pb-8 border-t flex items-center gap-3 shadow-inner">
          <button onClick={() => chatImageRef.current?.click()} className="p-2 text-gray-400 hover:text-[#9B4A4E]"><ImageIcon size={22} /></button>
          <input type="file" ref={chatImageRef} className="hidden" accept="image/*" onChange={handleChatImage} />
          <input type="text" value={inputValue} onChange={(e) => setInputValue(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()} placeholder="اكتب رسالتك..." className="flex-1 bg-gray-50 rounded-full px-4 py-3 text-xs text-right border-none outline-none focus:ring-1 focus:ring-[#9B4A4E]/20" dir="rtl" />
          <button onClick={handleSendMessage} className="bg-[#9B4A4E] text-white p-3 rounded-full shadow-lg active:scale-90 transition-all"><Send size={18} className="rotate-180" /></button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-3xl p-6 shadow-xl border border-gray-100">
      {hasExistingComplaint ? (
        <div className="flex flex-col items-center text-center py-4">
          <div className="w-20 h-20 bg-green-50 rounded-full flex items-center justify-center mb-4"><MessageSquareText size={36} className="text-green-600" /></div>
          <h3 className="font-bold text-gray-800">طلبك قيد المراجعة الفورية</h3>
          <p className="text-[11px] text-gray-500 mt-2 mb-6 px-4">تم تسجيل بياناتك. تواصل مع الوكيل ناصر لمتابعة الاسترداد.</p>
          <button onClick={() => setIsChatActive(true)} className="w-full bg-[#9B4A4E] text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 shadow-lg active:scale-95 transition-transform">
            <Paperclip size={20} /> عرض المرفقات والدردشة المباشرة
          </button>
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-4">
          <input type="text" required placeholder="رابط المنصة" value={formData.link} onChange={e => setFormData({...formData, link: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border-none shadow-inner" />
          <div className="grid grid-cols-2 gap-3">
            <input type="text" required placeholder="رقم المهمة" value={formData.missionId} onChange={e => setFormData({...formData, missionId: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border-none shadow-inner" />
            <input type="number" required placeholder="المبلغ USDT" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border-none shadow-inner" />
          </div>
          <div onClick={() => fileInputRef.current?.click()} className="w-full aspect-video rounded-2xl border-2 border-dashed border-gray-200 flex flex-col items-center justify-center bg-gray-50 cursor-pointer overflow-hidden relative group">
            {imagePreview ? <img src={imagePreview} className="w-full h-full object-cover" /> : <div className="text-center transition-transform group-hover:scale-110"><Camera className="mx-auto text-gray-300 mb-2" size={32} /><p className="text-[9px] text-gray-400 font-bold">أرفق لقطة شاشة للمهمة</p></div>}
          </div>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) { setSelectedImage(f); const r = new FileReader(); r.onloadend = () => setImagePreview(r.result as string); r.readAsDataURL(f); } }} />
          <button type="submit" disabled={isSubmitting || !selectedImage} className="w-full bg-[#9B4A4E] text-white font-bold py-4 rounded-2xl disabled:opacity-50 flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-all">
            {isSubmitting ? <Loader2 className="animate-spin" /> : 'تقديم الشكوى الآن'}
          </button>
        </form>
      )}
    </div>
  );
};

export default RecoveryForm;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { supabase } from '../lib/supabase.ts';
import { MessageSquare, User, Clock, ChevronLeft, Send, Image as ImageIcon, CheckCheck, Loader2, Search, AlertCircle, RefreshCcw, ExternalLink, Paperclip, Pin, Sparkles, WifiOff } from 'lucide-react';

interface Complaint {
  id: string;
  created_at: string;
  amount: number;
  mission_id: string;
  platform_link: string;
  user_id: string;
  last_activity: string; 
  screenshot_url?: string;
  profiles?: {
    full_name: string;
    customer_code: string;
  };
}

const AdminDashboard: React.FC = () => {
  const [complaints, setComplaints] = useState<Complaint[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const selectedIdRef = useRef<string | null>(null);
  const messagesRef = useRef<any[]>([]);

  // مزامنة المراجع لضمان الوصول للقيم الأحدث داخل ردود فعل Realtime
  useEffect(() => {
    selectedIdRef.current = selectedId;
    if (selectedId) {
      loadMessages(selectedId);
    } else {
      setMessages([]);
      messagesRef.current = [];
    }
  }, [selectedId]);

  useEffect(() => {
    messagesRef.current = messages;
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const loadMessages = async (id: string) => {
    const { data } = await supabase
      .from('complaint_messages')
      .select('*')
      .eq('complaint_id', id)
      .order('created_at', { ascending: true });
    if (data) {
      setMessages(data);
      messagesRef.current = data;
    }
  };

  const fetchComplaints = async () => {
    try {
      const { data: rawComps, error: rawError } = await supabase
        .from('complaints')
        .select('*')
        .order('created_at', { ascending: false });

      if (rawError) throw rawError;
      if (!rawComps) return;

      const userIds = [...new Set(rawComps.map(c => c.user_id))];
      const { data: profiles } = await supabase
        .from('profiles')
        .select('id, full_name, customer_code')
        .in('id', userIds);

      const { data: lastMsgs } = await supabase
        .from('complaint_messages')
        .select('complaint_id, created_at')
        .order('created_at', { ascending: false });

      const processed = rawComps.map(c => {
        const latestMsg = lastMsgs?.find(m => m.complaint_id === c.id);
        return {
          ...c,
          profiles: profiles?.find(p => p.id === c.user_id),
          last_activity: latestMsg ? latestMsg.created_at : c.created_at
        } as Complaint;
      });

      setComplaints(processed);
    } catch (err: any) {
      console.error("Fetch Error:", err);
      setError("خطأ في جلب البيانات.");
    } finally {
      setLoading(false);
    }
  };

  // المزامنة الفورية (Real-time) - واتساب بروتوكول
  useEffect(() => {
    fetchComplaints();

    const channel = supabase.channel('whatsapp_admin_v3')
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaint_messages' 
      }, (payload) => {
        const newMsg = payload.new;

        // 1. تحديث ترتيب القائمة (تصدر المحادثة النشطة)
        setComplaints(prev => {
          const index = prev.findIndex(c => c.id === newMsg.complaint_id);
          if (index === -1) {
            // إذا كانت الشكوى غير موجودة، نقوم بجلب الكل مجدداً لضمان التحديث
            fetchComplaints();
            return prev;
          }

          const updated = [...prev];
          const item = { ...updated[index], last_activity: newMsg.created_at };
          updated.splice(index, 1);
          updated.unshift(item);
          return updated;
        });

        // 2. تحديث الرسائل في المحادثة المفتوحة (لحظياً)
        if (selectedIdRef.current === newMsg.complaint_id) {
          // التحقق من عدم التكرار باستخدام المعرف (ID)
          const exists = messagesRef.current.some(m => String(m.id) === String(newMsg.id));
          if (!exists) {
            setMessages(prev => [...prev, newMsg]);
          }
        }
      })
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaints' 
      }, () => {
        fetchComplaints();
      })
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') console.log('Admin Realtime: Connected');
      });

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !selectedId) return;
    const text = inputValue;
    setInputValue('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      // تحديث متفائل للواجهة (Optimistic UI) لضمان السرعة الفائقة
      const tempId = `temp-${Date.now()}`;
      const optimisticMsg = {
        id: tempId,
        complaint_id: selectedId,
        user_id: user.id,
        text: text,
        sender: 'support',
        created_at: new Date().toISOString()
      };

      setMessages(prev => [...prev, optimisticMsg]);

      const { data: sentMsg, error: sendError } = await supabase.from('complaint_messages').insert([{
        complaint_id: selectedId,
        user_id: user.id,
        text: text,
        sender: 'support'
      }]).select().single();

      if (sendError) throw sendError;

      // استبدال الرسالة المؤقتة بالرسالة الحقيقية
      setMessages(prev => prev.map(m => m.id === tempId ? sentMsg : m));

    } catch (err: any) {
      console.error("Send Error:", err);
      setInputValue(text);
      setMessages(prev => prev.filter(m => !String(m.id).startsWith('temp-')));
      alert("فشل الإرسال، حاول مجدداً.");
    }
  };

  const filteredComplaints = useMemo(() => {
    return complaints
      .filter(c => 
        searchQuery === '' ||
        c.profiles?.full_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.mission_id?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.amount.toString().includes(searchQuery)
      )
      .sort((a, b) => new Date(b.last_activity).getTime() - new Date(a.last_activity).getTime());
  }, [complaints, searchQuery]);

  if (loading && complaints.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center p-24 gap-4">
        <Loader2 className="animate-spin text-[#9B4A4E]" size={40} />
        <p className="text-gray-400 text-[10px] font-black tracking-widest">تنشيط المزامنة المباشرة...</p>
      </div>
    );
  }

  if (selectedId) {
    const comp = complaints.find(c => c.id === selectedId);
    return (
      <div className="fixed inset-0 z-[110] bg-[#F8FAFC] flex flex-col max-w-[430px] mx-auto animate-in slide-in-from-left duration-200">
        <div className="bg-[#9B4A4E] text-white px-4 pt-12 pb-4 flex items-center gap-3 shadow-xl z-30">
          <button onClick={() => setSelectedId(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <ChevronLeft size={24} />
          </button>
          <div className="flex-1 text-right">
            <h2 className="text-sm font-bold truncate">{comp?.profiles?.full_name || 'عميل'}</h2>
            <p className="text-[9px] opacity-70">كود: {comp?.profiles?.customer_code || '---'}</p>
          </div>
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center border border-white/10 shadow-inner">
             <User size={20} />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 pb-32 bg-[#e5ddd5]">
          <div className="bg-white p-4 rounded-3xl border border-[#9B4A4E]/20 shadow-md text-right sticky top-0 z-20">
             <div className="flex items-center gap-2 mb-3 text-[#9B4A4E] font-bold text-[10px] border-b border-gray-50 pb-2">
                <Pin size={14} className="rotate-45" /> البيانات الأصلية للطلب
             </div>
             <div className="grid grid-cols-2 gap-3 mb-3 text-right">
               <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100/50">
                 <p className="text-gray-400 text-[8px] mb-1 font-bold">المبلغ</p>
                 <p className="text-red-600 font-black text-xs">{comp?.amount} USDT</p>
               </div>
               <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100/50">
                 <p className="text-gray-400 text-[8px] mb-1 font-bold">المهمة</p>
                 <p className="text-gray-800 font-bold text-xs">#{comp?.mission_id}</p>
               </div>
             </div>
          </div>

          {messages.map((m) => (
            <div key={m.id} className={`max-w-[85%] flex flex-col ${m.sender === 'support' ? 'self-end' : 'self-start'}`}>
               <div className={`rounded-2xl overflow-hidden shadow-sm ${m.sender === 'support' ? 'bg-[#dcf8c6] text-gray-800 rounded-tr-none border border-black/5' : 'bg-white text-gray-800 rounded-tl-none border border-gray-200'}`}>
                 {m.image_url && (
                   <img src={m.image_url} className="w-full max-h-96 object-contain bg-black/5 cursor-pointer" onClick={() => window.open(m.image_url, '_blank')} />
                 )}
                 {m.text && <div className="p-3 text-[11px] text-right whitespace-pre-wrap leading-relaxed font-medium">{m.text}</div>}
                 <div className={`px-3 pb-1.5 flex items-center gap-1 text-[8px] ${m.sender === 'support' ? 'justify-start opacity-60' : 'justify-end opacity-40'}`}>
                   <span>{new Date(m.created_at).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
                   {m.sender === 'support' && <CheckCheck size={10} />}
                 </div>
               </div>
            </div>
          ))}
          <div ref={chatEndRef} />
        </div>

        <div className="p-4 border-t flex items-center gap-2 bg-white pb-10 shadow-[0_-10px_25px_rgba(0,0,0,0.05)] z-30">
          <input 
            type="text" 
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
            placeholder="اكتب رد المسؤول..."
            className="flex-1 bg-gray-50 rounded-full px-5 py-4 text-xs text-right border border-gray-100 outline-none focus:border-[#9B4A4E] transition-all"
            dir="rtl"
          />
          <button onClick={handleSendMessage} className="bg-[#9B4A4E] text-white p-4 rounded-full shadow-lg active:scale-90 transition-transform">
            <Send size={20} className="rotate-180" />
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4 py-2 animate-in fade-in duration-500">
      <div className="bg-white rounded-[32px] p-6 shadow-sm border border-gray-100 mb-6 mx-1">
         <div className="flex items-center justify-between mb-6 text-right">
            <button onClick={fetchComplaints} className="p-2 text-gray-300 hover:text-[#9B4A4E]">
              <RefreshCcw size={18} className={loading ? 'animate-spin text-[#9B4A4E]' : ''} />
            </button>
            <div>
              <h2 className="font-black text-gray-800 text-lg">لوحة الرصد الفوري</h2>
              <div className="flex items-center gap-1 justify-end mt-1">
                 <span className="text-[10px] text-green-500 font-black">المزامنة نَشطة</span>
                 <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_5px_green]"></div>
              </div>
            </div>
         </div>
         <div className="relative">
            <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
            <input 
              type="text" 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="ابحث بالاسم أو المهمة..." 
              className="w-full bg-gray-50 rounded-2xl py-4 px-12 text-xs text-right border-none shadow-inner outline-none focus:ring-1 focus:ring-[#9B4A4E]/20" 
              dir="rtl" 
            />
         </div>
      </div>

      <div className="space-y-3 px-1 pb-32">
        {filteredComplaints.length === 0 && !loading ? (
          <div className="text-center py-24 flex flex-col items-center gap-4 text-gray-400">
            <MessageSquare size={40} />
            <p className="text-xs font-black">لا توجد محادثات نشطة</p>
          </div>
        ) : (
          filteredComplaints.map(c => {
            const isJustActive = (new Date().getTime() - new Date(c.last_activity).getTime()) < 30000;
            return (
              <button 
                key={c.id} 
                onClick={() => setSelectedId(c.id)}
                className={`w-full bg-white p-5 rounded-[28px] flex items-center gap-4 border shadow-sm active:scale-[0.98] transition-all text-right hover:border-[#9B4A4E]/30 relative overflow-hidden ${isJustActive ? 'border-[#9B4A4E]/30 ring-1 ring-[#9B4A4E]/5 shadow-md' : 'border-gray-50'}`}
              >
                {isJustActive && (
                  <div className="absolute top-0 right-0 p-1.5 bg-[#9B4A4E] text-white rounded-bl-xl shadow-md flex items-center gap-1">
                     <Sparkles size={10} />
                     <span className="text-[7px] font-black">جديد</span>
                  </div>
                )}
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${isJustActive ? 'bg-[#9B4A4E]/10 text-[#9B4A4E]' : 'bg-gray-50 text-gray-400'}`}>
                  <User size={28} strokeWidth={1.5} />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex justify-between items-start mb-1">
                    <span className="text-[8px] font-bold text-gray-400">
                      {new Date(c.last_activity).toLocaleTimeString('ar-EG', {hour:'2-digit', minute:'2-digit'})}
                    </span>
                    <h4 className="font-bold text-gray-800 text-sm truncate ml-2">
                      {c.profiles?.full_name || 'عميل'}
                    </h4>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-[11px] font-black text-[#9B4A4E]">{c.amount} USDT</span>
                    <p className="text-[9px] text-gray-400 font-bold bg-gray-50 px-2 py-0.5 rounded-md">
                      #{c.mission_id}
                    </p>
                  </div>
                </div>
                <ChevronLeft size={16} className="text-gray-200" />
              </button>
            );
          })
        )}
      </div>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useRef, useEffect } from 'react';
import { Gavel, Send, ChevronRight, MoreVertical, CheckCheck, Loader2, MessageSquareText, Camera, Image as ImageIcon, Paperclip } from 'lucide-react';
import { supabase } from '../lib/supabase.ts';

interface Message {
  id: any;
  text?: string;
  imageUrl?: string;
  sender: 'user' | 'support';
  time: string;
}

const RecoveryForm: React.FC = () => {
  const [isChatActive, setIsChatActive] = useState(false);
  const [hasExistingComplaint, setHasExistingComplaint] = useState(false);
  const [currentComplaintId, setCurrentComplaintId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isChatUploading, setIsChatUploading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [formData, setFormData] = useState({ link: '', missionId: '', amount: '', reason: 'تجميد الرصيد' });
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const messagesRef = useRef<Message[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatImageRef = useRef<HTMLInputElement>(null);

  const formatTime = (date: string | Date) => new Date(date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  // مزامنة المرجع
  useEffect(() => {
    messagesRef.current = messages;
    if (isChatActive) {
      scrollToBottom();
    }
  }, [messages, isChatActive]);

  const scrollToBottom = () => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  };

  // التحقق الأولي
  useEffect(() => {
    async function checkStatus() {
      try {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return;

        const { data: complaint } = await supabase
          .from('complaints')
          .select('*')
          .eq('user_id', user.id)
          .order('created_at', { ascending: false })
          .limit(1)
          .maybeSingle();

        if (complaint) {
          setHasExistingComplaint(true);
          setCurrentComplaintId(complaint.id);

          const { data: dbMsgs } = await supabase
            .from('complaint_messages')
            .select('*')
            .eq('complaint_id', complaint.id)
            .order('created_at', { ascending: true });

          if (dbMsgs) {
            const mapped = dbMsgs.map(m => ({ 
              id: m.id, 
              text: m.text, 
              imageUrl: m.image_url, 
              sender: m.sender, 
              time: formatTime(m.created_at) 
            }));
            setMessages(mapped);
            messagesRef.current = mapped;
          }
        }
      } catch (e) {
        console.error(e);
      } finally { 
        setLoading(false); 
      }
    }
    checkStatus();
  }, []);

  // المزامنة الفورية (Real-time) للعميل
  useEffect(() => {
    if (!currentComplaintId) return;

    const channel = supabase.channel(`whatsapp_client_v3_${currentComplaintId}`)
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaint_messages', 
        filter: `complaint_id=eq.${currentComplaintId}` 
      }, (payload) => {
        const newMsg = payload.new;

        // التحقق من عدم التكرار
        const exists = messagesRef.current.some(m => String(m.id) === String(newMsg.id));
        if (!exists) {
          const mappedMsg: Message = {
            id: newMsg.id,
            text: newMsg.text,
            imageUrl: newMsg.image_url,
            sender: newMsg.sender,
            time: formatTime(newMsg.created_at)
          };
          setMessages(prev => [...prev, mappedMsg]);
        }
      })
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') console.log('Client Realtime: Connected');
      });

    return () => {
      supabase.removeChannel(channel);
    };
  }, [currentComplaintId]);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !currentComplaintId) return;
    const text = inputValue;
    const now = new Date();
    setInputValue('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      // تحديث متفائل (Optimistic Update)
      const tempId = `temp-${Date.now()}`;
      const optimisticMsg: Message = {
        id: tempId,
        text: text,
        sender: 'user',
        time: formatTime(now)
      };
      setMessages(prev => [...prev, optimisticMsg]);

      const { data: sentMsg, error } = await supabase.from('complaint_messages').insert([{ 
        complaint_id: currentComplaintId, 
        user_id: user.id, 
        text: text, 
        sender: 'user' 
      }]).select().single();

      if (error) throw error;

      // تحديث المعرف المؤقت
      setMessages(prev => prev.map(m => m.id === tempId ? {
        id: sentMsg.id,
        text: sentMsg.text,
        imageUrl: sentMsg.image_url,
        sender: sentMsg.sender,
        time: formatTime(sentMsg.created_at)
      } : m));

    } catch (e) {
      console.error(e);
      setInputValue(text);
      setMessages(prev => prev.filter(m => !String(m.id).startsWith('temp-')));
    }
  };

  const handleChatImage = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !currentComplaintId) return;
    setIsChatUploading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const fileName = `${user.id}/${Date.now()}.jpg`;
      await supabase.storage.from('chat_images').upload(fileName, file);
      const { data: { publicUrl } } = supabase.storage.from('chat_images').getPublicUrl(fileName);

      await supabase.from('complaint_messages').insert([{ 
        complaint_id: currentComplaintId, 
        user_id: user.id, 
        image_url: publicUrl, 
        sender: 'user' 
      }]);
      // سيتم التحديث التلقائي عبر Real-time
    } catch (e) {
      console.error(e);
    } finally { 
      setIsChatUploading(false); 
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedImage) return;
    setIsSubmitting(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const fileName = `initial/${user.id}-${Date.now()}.jpg`;
      await supabase.storage.from('complaints').upload(fileName, selectedImage);
      const { data: { publicUrl } } = supabase.storage.from('complaints').getPublicUrl(fileName);

      const { data: comp, error: compErr } = await supabase.from('complaints').insert([{ 
        user_id: user.id, 
        platform_link: formData.link, 
        mission_id: formData.missionId, 
        amount: parseFloat(formData.amount), 
        reason: formData.reason, 
        screenshot_url: publicUrl 
      }]).select().single();

      if (compErr) throw compErr;

      if (comp) {
        const reportText = `📋 *تفاصيل الطلب:*\nالرابط: ${formData.link}\nالمهمة: #${formData.missionId}\nالمبلغ: ${formData.amount} USDT`;
        await supabase.from('complaint_messages').insert([
          { complaint_id: comp.id, user_id: user.id, image_url: publicUrl, sender: 'user' },
          { complaint_id: comp.id, user_id: user.id, text: reportText, sender: 'user' }
        ]);

        setCurrentComplaintId(comp.id);
        setHasExistingComplaint(true);
      }
    } catch (e) {
      console.error(e);
      alert("حدث خطأ في تقديم الشكوى.");
    } finally { 
      setIsSubmitting(false); 
    }
  };

  if (loading) return <div className="p-10 flex justify-center"><Loader2 className="animate-spin text-[#9B4A4E]" /></div>;

  if (isChatActive) {
    return (
      <div className="fixed inset-0 z-[100] bg-[#F4F7F9] flex flex-col max-w-[430px] mx-auto animate-in fade-in duration-200">
        <div className="bg-[#9B4A4E] text-white px-4 pt-12 pb-4 flex items-center gap-3 shadow-lg">
          <button onClick={() => setIsChatActive(false)}><ChevronRight size={28} /></button>
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center overflow-hidden border border-white/10 shadow-inner">
             <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Naser" className="w-full h-full" />
          </div>
          <div className="flex-1 text-right">
            <h2 className="text-sm font-bold">ناصر - مراجعة المرفقات</h2>
            <p className="text-[9px] opacity-70">متصل الآن لمراجعة طلبك</p>
          </div>
          <MoreVertical size={20} className="opacity-40" />
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 flex flex-col bg-[#e5ddd5]">
          {messages.map((msg) => (
            <div key={msg.id} className={`max-w-[85%] ${msg.sender === 'user' ? 'self-end' : 'self-start'}`}>
              <div className={`rounded-2xl overflow-hidden shadow-sm ${msg.sender === 'user' ? 'bg-[#dcf8c6] text-gray-800 rounded-tr-none border border-black/5' : 'bg-white text-gray-800 rounded-tl-none border border-gray-200'}`}>
                {msg.imageUrl && <img src={msg.imageUrl} className="w-full max-h-64 object-cover cursor-pointer" onClick={() => window.open(msg.imageUrl, '_blank')} />}
                {msg.text && <div className="p-3 text-[11px] text-right whitespace-pre-wrap leading-relaxed font-medium">{msg.text}</div>}
                <div className={`px-3 pb-1.5 flex items-center gap-1 text-[8px] opacity-60 ${msg.sender === 'user' ? 'justify-start' : 'justify-end'}`}>
                  <span>{msg.time}</span>
                  {msg.sender === 'user' && <CheckCheck size={10} />}
                </div>
              </div>
            </div>
          ))}
          {isChatUploading && <div className="self-end text-[9px] text-[#9B4A4E] animate-pulse">جاري إرسال المرفق...</div>}
          <div ref={chatEndRef} />
        </div>

        <div className="bg-white p-4 pb-8 border-t flex items-center gap-3 shadow-inner">
          <button onClick={() => chatImageRef.current?.click()} className="p-2 text-gray-400 hover:text-[#9B4A4E]"><ImageIcon size={22} /></button>
          <input type="file" ref={chatImageRef} className="hidden" accept="image/*" onChange={handleChatImage} />
          <input type="text" value={inputValue} onChange={(e) => setInputValue(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()} placeholder="اكتب رسالتك..." className="flex-1 bg-gray-50 rounded-full px-4 py-3 text-xs text-right border-none outline-none focus:ring-1 focus:ring-[#9B4A4E]/20" dir="rtl" />
          <button onClick={handleSendMessage} className="bg-[#9B4A4E] text-white p-3 rounded-full shadow-lg active:scale-90 transition-all"><Send size={18} className="rotate-180" /></button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-3xl p-6 shadow-xl border border-gray-100">
      {hasExistingComplaint ? (
        <div className="flex flex-col items-center text-center py-4">
          <div className="w-20 h-20 bg-green-50 rounded-full flex items-center justify-center mb-4"><MessageSquareText size={36} className="text-green-600" /></div>
          <h3 className="font-bold text-gray-800">طلبك قيد المراجعة الفورية</h3>
          <p className="text-[11px] text-gray-500 mt-2 mb-6 px-4">تم تسجيل بياناتك. تواصل مع الوكيل ناصر لمتابعة الاسترداد.</p>
          <button onClick={() => setIsChatActive(true)} className="w-full bg-[#9B4A4E] text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 shadow-lg active:scale-95 transition-transform">
            <Paperclip size={20} /> عرض المرفقات والدردشة المباشرة
          </button>
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-4">
          <input type="text" required placeholder="رابط المنصة" value={formData.link} onChange={e => setFormData({...formData, link: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border-none shadow-inner" />
          <div className="grid grid-cols-2 gap-3">
            <input type="text" required placeholder="رقم المهمة" value={formData.missionId} onChange={e => setFormData({...formData, missionId: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border-none shadow-inner" />
            <input type="number" required placeholder="المبلغ USDT" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full bg-gray-50 rounded-xl px-4 py-3 text-xs text-right border-none shadow-inner" />
          </div>
          <div onClick={() => fileInputRef.current?.click()} className="w-full aspect-video rounded-2xl border-2 border-dashed border-gray-200 flex flex-col items-center justify-center bg-gray-50 cursor-pointer overflow-hidden relative group">
            {imagePreview ? <img src={imagePreview} className="w-full h-full object-cover" /> : <div className="text-center transition-transform group-hover:scale-110"><Camera className="mx-auto text-gray-300 mb-2" size={32} /><p className="text-[9px] text-gray-400 font-bold">أرفق لقطة شاشة للمهمة</p></div>}
          </div>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) { setSelectedImage(f); const r = new FileReader(); r.onloadend = () => setImagePreview(r.result as string); r.readAsDataURL(f); } }} />
          <button type="submit" disabled={isSubmitting || !selectedImage} className="w-full bg-[#9B4A4E] text-white font-bold py-4 rounded-2xl disabled:opacity-50 flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-all">
            {isSubmitting ? <Loader2 className="animate-spin" /> : 'تقديم الشكوى الآن'}
          </button>
        </form>
      )}
    </div>
  );
};

export default RecoveryForm;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { supabase } from '../lib/supabase.ts';
import { MessageSquare, User, Clock, ChevronLeft, Send, Image as ImageIcon, CheckCheck, Loader2, Search, AlertCircle, RefreshCcw, ExternalLink, Paperclip, Pin, Sparkles, WifiOff, MoreVertical, Phone, Video } from 'lucide-react';

interface Complaint {
  id: string;
  created_at: string;
  amount: number;
  mission_id: string;
  platform_link: string;
  user_id: string;
  last_activity: string; 
  screenshot_url?: string;
  profiles?: {
    full_name: string;
    customer_code: string;
  };
}

const AdminDashboard: React.FC = () => {
  const [complaints, setComplaints] = useState<Complaint[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const selectedIdRef = useRef<string | null>(null);
  const messagesRef = useRef<any[]>([]);

  useEffect(() => {
    selectedIdRef.current = selectedId;
    if (selectedId) {
      loadMessages(selectedId);
    } else {
      setMessages([]);
      messagesRef.current = [];
    }
  }, [selectedId]);

  useEffect(() => {
    messagesRef.current = messages;
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const loadMessages = async (id: string) => {
    try {
      const { data } = await supabase
        .from('complaint_messages')
        .select('*')
        .eq('complaint_id', id)
        .order('created_at', { ascending: true });

      if (data && JSON.stringify(data) !== JSON.stringify(messagesRef.current)) {
        setMessages(data);
        messagesRef.current = data;
      }
    } catch (e) {
      console.error(e);
    }
  };

  const fetchComplaints = async (showLoading = false) => {
    if (showLoading) setLoading(true);
    try {
      const { data: rawComps, error: rawError } = await supabase
        .from('complaints')
        .select('*')
        .order('created_at', { ascending: false });

      if (rawError) throw rawError;
      if (!rawComps) return;

      const userIds = [...new Set(rawComps.map(c => c.user_id))];
      const { data: profiles } = await supabase
        .from('profiles')
        .select('id, full_name, customer_code')
        .in('id', userIds);

      const { data: lastMsgs } = await supabase
        .from('complaint_messages')
        .select('complaint_id, created_at')
        .order('created_at', { ascending: false });

      const processed = rawComps.map(c => {
        const latestMsg = lastMsgs?.find(m => m.complaint_id === c.id);
        return {
          ...c,
          profiles: profiles?.find(p => p.id === c.user_id),
          last_activity: latestMsg ? latestMsg.created_at : c.created_at
        } as Complaint;
      });

      setComplaints(processed);
    } catch (err: any) {
      console.error("Fetch Error:", err);
      setError("خطأ في جلب البيانات.");
    } finally {
      if (showLoading) setLoading(false);
    }
  };

  useEffect(() => {
    fetchComplaints(true);

    const channel = supabase.channel('whatsapp_admin_final')
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaint_messages' 
      }, (payload) => {
        const newMsg = payload.new;

        setComplaints(prev => {
          const index = prev.findIndex(c => c.id === newMsg.complaint_id);
          if (index === -1) {
            fetchComplaints();
            return prev;
          }
          const updated = [...prev];
          const item = { ...updated[index], last_activity: newMsg.created_at };
          updated.splice(index, 1);
          updated.unshift(item);
          return updated;
        });

        if (selectedIdRef.current === newMsg.complaint_id) {
          const exists = messagesRef.current.some(m => String(m.id) === String(newMsg.id));
          if (!exists) {
            setMessages(prev => [...prev, newMsg]);
          }
        }
      })
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'complaints' 
      }, () => {
        fetchComplaints();
      })
      .subscribe();

    const interval = setInterval(() => {
      fetchComplaints();
      if (selectedIdRef.current) {
        loadMessages(selectedIdRef.current);
      }
    }, 2000);

    return () => {
      supabase.removeChannel(channel);
      clearInterval(interval);
    };
  }, []);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !selectedId) return;
    const text = inputValue;
    setInputValue('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const tempId = `temp-${Date.now()}`;
      const optimisticMsg = {
        id: tempId,
        complaint_id: selectedId,
        user_id: user.id,
        text: text,
        sender: 'support',
        created_at: new Date().toISOString()
      };

      setMessages(prev => [...prev, optimisticMsg]);

      const { data: sentMsg, error: sendError } = await supabase.from('complaint_messages').insert([{
        complaint_id: selectedId,
        user_id: user.id,
        text: text,
        sender: 'support'
      }]).select().single();

      if (sendError) throw sendError;
      setMessages(prev => prev.map(m => m.id === tempId ? sentMsg : m));

    } catch (err: any) {
      console.error("Send Error:", err);
      setInputValue(text);
      setMessages(prev => prev.filter(m => !String(m.id).startsWith('temp-')));
    }
  };

  const filteredComplaints = useMemo(() => {
    return complaints
      .filter(c => 
        searchQuery === '' ||
        c.profiles?.full_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.mission_id?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.amount.toString().includes(searchQuery)
      )
      .sort((a, b) => new Date(b.last_activity).getTime() - new Date(a.last_activity).getTime());
  }, [complaints, searchQuery]);

  if (loading && complaints.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center p-24 gap-4">
        <Loader2 className="animate-spin text-[#9B4A4E]" size={40} />
        <p className="text-gray-400 text-[10px] font-black tracking-widest">تنشيط المزامنة اللحظية...</p>
      </div>
    );
  }

  if (selectedId) {
    const comp = complaints.find(c => c.id === selectedId);
    return (
      <div className="fixed inset-0 z-[110] bg-[#e5ddd5] flex flex-col max-w-[430px] mx-auto animate-in slide-in-from-left duration-200">
        {/* WhatsApp Style Header */}
        <div className="bg-[#075e54] text-white px-3 pt-10 pb-3 flex items-center gap-2 shadow-md z-30">
          <button onClick={() => setSelectedId(null)} className="p-1 hover:bg-white/10 rounded-full transition-colors">
            <ChevronLeft size={28} />
          </button>
          <div className="w-10 h-10 bg-gray-200 rounded-full flex items-center justify-center overflow-hidden border border-white/20 shadow-sm flex-shrink-0">
             <img src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${comp?.profiles?.full_name || 'user'}`} className="w-full h-full object-cover" />
          </div>
          <div className="flex-1 text-right overflow-hidden">
            <h2 className="text-sm font-bold truncate leading-tight">{comp?.profiles?.full_name || 'عميل'}</h2>
            <div className="flex items-center gap-1 justify-end">
               <div className="w-1.5 h-1.5 bg-green-400 rounded-full"></div>
               <p className="text-[9px] opacity-80">متصل الآن</p>
            </div>
          </div>
          <div className="flex items-center gap-4 px-2 opacity-90">
             <Video size={18} />
             <Phone size={16} />
             <MoreVertical size={18} />
          </div>
        </div>

        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3 pb-24" style={{ backgroundImage: 'url("https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png")', backgroundSize: 'contain' }}>
          {/* Data Card (Stays at top) */}
          <div className="bg-white/95 backdrop-blur-sm p-4 rounded-2xl border border-[#075e54]/10 shadow-sm text-right mb-6">
             <div className="flex items-center gap-2 mb-2 text-[#075e54] font-bold text-[10px] border-b border-gray-100 pb-1">
                <Pin size={12} className="rotate-45" /> تفاصيل الطلب المتنازع عليه
             </div>
             <div className="grid grid-cols-2 gap-2 text-right">
               <div className="bg-gray-50/50 p-2 rounded-xl">
                 <p className="text-gray-400 text-[8px] mb-0.5 font-bold">المبلغ</p>
                 <p className="text-red-600 font-black text-xs">{comp?.amount} USDT</p>
               </div>
               <div className="bg-gray-50/50 p-2 rounded-xl">
                 <p className="text-gray-400 text-[8px] mb-0.5 font-bold">المهمة</p>
